    private static String tameDisplayName(TameData data) {
        if (data == null || data.name == null || data.name.isBlank()) {
            return "unknown";
        }
        return data.name;
    }

    private static String paymentPriceLabel(int xpCost, int approvedItemCost, boolean allowXp) {
        return paymentPriceLabel(xpCost, approvedItemCost, 1, allowXp);
    }

    private static String paymentPriceLabel(int xpCost, int approvedItemCost, int totemCost, boolean allowXp) {
        int normalizedXp = Math.max(0, xpCost);
        int normalizedItems = Math.max(1, approvedItemCost);
        int normalizedTotems = Math.max(1, totemCost);
        List<String> parts = new ArrayList<>();
        if (allowXp) {
            parts.add(normalizedXp + " XP");
        }
        if (approvedItemCost > 0) {
            parts.add(formatApprovedItemRequirement(normalizedItems));
        }
        parts.add(normalizedTotems + " vanilla totem" + (normalizedTotems == 1 ? "" : "s"));
        return String.join(" or ", parts);
    }

    private static String teleportPriceLabel(int xpCost) {
        return Math.max(0, xpCost) + " XP points";
    }

    private static String pricedTameLabel(TameData data, String price) {
        return tameDisplayName(data) + " (" + price + ")";
    }

    private static void sendAffordabilityFailures(ServerPlayer player, String prefix, List<String> failures) {
        if (player == null || failures == null || failures.isEmpty()) {
            return;
        }
        player.sendSystemMessage(Component.literal(prefix + ": " + String.join("; ", failures)).withStyle(ChatFormatting.RED));
    }

    private static PaymentResult evaluatePayment(ServerPlayer player, int xpCost, int approvedItemCost, int totemCost, boolean allowXp, String purpose, boolean consume) {
        if (player == null) {
            return PaymentResult.fail("player unavailable");
        }
        ItemStack held = player.getMainHandItem();
        int normalizedXp = Math.max(0, xpCost);
        int normalizedItems = Math.max(1, approvedItemCost);
        int normalizedTotems = Math.max(1, totemCost);
        if (isReincarnationTotem(held) && held.getCount() >= normalizedTotems) {
            if (consume) {
                held.shrink(normalizedTotems);
            }
            return PaymentResult.ok(normalizedTotems + " vanilla totem" + (normalizedTotems == 1 ? "" : "s"));
        }
        int requiredPaymentPoints = normalizedItems * FOOD_POINTS_PER_APPROVED_ITEM;
        int heldPaymentPoints = approvedOrFoodPaymentPoints(held);
        if (heldPaymentPoints >= requiredPaymentPoints) {
            if (consume) {
                consumeApprovedOrFoodPaymentPoints(held, requiredPaymentPoints);
            }
            return PaymentResult.ok(formatApprovedItemRequirement(normalizedItems));
        }
        int currentXp = currentXpPoints(player);
        if (allowXp && currentXp >= normalizedXp) {
            if (consume && normalizedXp > 0) {
                player.giveExperiencePoints(-normalizedXp);
            }
            return PaymentResult.ok(normalizedXp + " XP points");
        }
        return PaymentResult.fail(describePaymentRequirement(player, normalizedXp, normalizedItems, normalizedTotems, allowXp, purpose, currentXp));
    }

    private static String describePaymentRequirement(ServerPlayer player, int xpCost, int approvedItemCost, int totemCost, boolean allowXp, String purpose, int currentXp) {
        StringBuilder builder = new StringBuilder();
        builder.append("Cannot afford ").append(purpose == null || purpose.isBlank() ? "this" : purpose).append(". Need ");
        boolean appended = false;
        if (allowXp) {
            builder.append(xpCost).append(" XP");
            appended = true;
        }
        if (approvedItemCost > 0) {
            if (appended) {
                builder.append(" or ");
            }
            builder.append(formatApprovedItemRequirement(approvedItemCost));
            appended = true;
        }
        if (appended) {
            builder.append(" or ").append(totemCost).append(" vanilla totem").append(totemCost == 1 ? "." : "s.");
        } else {
            builder.append(totemCost).append(" vanilla totem").append(totemCost == 1 ? "." : "s.");
        }
        return builder.toString();
    }

    private static String approvedItemNamesDisplay() {
        List<String> names = new ArrayList<>();
        for (String id : TameRegistry.APPROVED_REINCARNATE_ITEMS) {
            names.add(approvedItemDisplayLabel(id) + " [normal]");
        }
        names.sort(String::compareToIgnoreCase);
        return String.join(", ", names);
    }

    private static boolean isApprovedReincarnationItem(ItemStack stack) {
        return approvedItemValue(stack) > 0 || stackFoodPointsPerItem(stack) > 0;
    }

    private static int approvedItemValue(ItemStack stack) {
        if (stack == null || stack.isEmpty()) {
            return 0;
        }
        ResourceLocation key = ForgeRegistries.ITEMS.getKey(stack.getItem());
        if (key == null) {
            return 0;
        }
        String id = key.toString().toLowerCase(Locale.ROOT);
        if (TameRegistry.APPROVED_REINCARNATE_ITEMS.contains(id)) {
            return stack.getCount() * 5;
        }
        return 0;
    }

    private static int approvedOrFoodPaymentPoints(ItemStack stack) {
        if (stack == null || stack.isEmpty()) {
            return 0;
        }
        int approvedItems = approvedItemValue(stack) / 5;
        if (approvedItems > 0) {
            return approvedItems * FOOD_POINTS_PER_APPROVED_ITEM;
        }
        return stackFoodPointsPerItem(stack) * stack.getCount();
    }

    private static void consumeApprovedOrFoodPaymentPoints(ItemStack stack, int requiredPaymentPoints) {
        if (stack == null || stack.isEmpty() || requiredPaymentPoints <= 0) {
            return;
        }
        int approvedItems = approvedItemValue(stack) / 5;
        if (approvedItems > 0) {
            int itemsToConsume = (int) Math.ceil(requiredPaymentPoints / (double) FOOD_POINTS_PER_APPROVED_ITEM);
            stack.shrink(itemsToConsume);
            return;
        }
        int foodPointsPerItem = stackFoodPointsPerItem(stack);
        if (foodPointsPerItem <= 0) {
            return;
        }
        int itemsToConsume = (int) Math.ceil(requiredPaymentPoints / (double) foodPointsPerItem);
        stack.shrink(itemsToConsume);
    }

    private static int stackFoodPointsPerItem(ItemStack stack) {
        if (stack == null || stack.isEmpty() || !stack.isEdible() || stack.getItem().getFoodProperties() == null) {
            return 0;
        }
        return Math.max(0, stack.getItem().getFoodProperties().getNutrition());
    }

    private static void consumeApprovedItemValue(ItemStack stack, int requiredValue) {
        if (stack == null || stack.isEmpty() || requiredValue <= 0) {
            return;
        }
        int requiredPaymentPoints = (int) Math.ceil(requiredValue / 5.0D) * FOOD_POINTS_PER_APPROVED_ITEM;
        consumeApprovedOrFoodPaymentPoints(stack, requiredPaymentPoints);
    }

    private static String formatApprovedItemRequirement(int approvedItemCost) {
        int normalizedItems = Math.max(1, approvedItemCost);
        int foodPoints = normalizedItems * FOOD_POINTS_PER_APPROVED_ITEM;
        return normalizedItems + " approved item" + (normalizedItems == 1 ? "" : "s") + " or " + foodPoints + " food points";
    }

    private static boolean isReincarnationTotem(ItemStack stack) {
        return stack != null && !stack.isEmpty() && stack.is(Items.TOTEM_OF_UNDYING);
    }

