    private static int teleportPet(CommandSourceStack source, String pet, MovementOrder orderOverride) {
        ServerPlayer p = source.getPlayer();
        TameData d = findOwnedTameAny(p.getUUID(), pet);
        if (d == null) return error(p, "Pet not found.");
        if (isDuelLocked(d)) return error(p, tameDisplayName(d) + " is in a duel. Use /tames dueltp.");
        if (d.stored) return error(p, tameDisplayName(d) + " is stored and can only be recovered with admin respawn.");
        if (d.dead || isDeadEntry(d.uuid)) return error(p, tameDisplayName(d) + " is dead and cannot be teleported.");
        if (d.horseType) {
            LivingEntity loadedHorse = findLoadedLivingEntity(source.getServer(), d.uuid);
            if (!(loadedHorse instanceof net.minecraft.world.entity.animal.horse.AbstractHorse)) {
                return error(p, "Horse is not currently loaded and cannot be teleported.");
            }
            boolean horseCrossDimension = loadedHorse.level() != p.level();
            TeleportPaymentResult horsePayment = payTeleportXp(p, teleportCostFor(d, horseCrossDimension), 1);
            if (!horsePayment.success) return error(p, horsePayment.error);
            if (!consumeHungerForCommandTeleport(p, d, null)) return 0;
            loadedHorse.teleportTo(p.serverLevel(), p.getX(), p.getY(), p.getZ(),
                    java.util.Set.of(), p.getYRot(), p.getXRot());
            p.sendSystemMessage(Component.literal("Teleport: " + d.name).withStyle(ChatFormatting.WHITE));
            return 1;
        }
        boolean crossDimension = isCrossDimension(d, p);
        int cost = teleportCostFor(d, crossDimension);
        TeleportPaymentResult payment = payTeleportXp(p, cost, 1);
        if (!payment.success) return error(p, payment.error);
        TamableAnimal ta = findLoadedOwnedTameByUuid(source, p.getUUID(), d.uuid);
        if (ta == null) {
            LivingEntity modified = findLoadedOwnedLivingTameByIdentity(source, p.getUUID(), d);
            if (modified != null && !(modified instanceof TamableAnimal)) {
                if (!consumeHungerForCommandTeleport(p, d, modified)) return 0;
                modified.teleportTo(p.serverLevel(), p.getX(), p.getY(), p.getZ(), java.util.Set.of(), p.getYRot(), p.getXRot());
                if (orderOverride != null && !d.horseType) {
                    applyLivingMovementOverride(modified, d, orderOverride);
                }
                p.sendSystemMessage(Component.literal("Teleport: " + d.name).withStyle(ChatFormatting.WHITE));
                return 1;
            }
            if (!consumeHungerForCommandTeleport(p, d, null)) return 0;
            UnloadedTpResult unloaded = tpUnloadedViaLanternOrRecover(source, p, d);
            if (!unloaded.success) return error(p, "Failed to tp unloaded tame: " + unloaded.error);
            TamableAnimal loadedAfterTeleport = findLoadedOwnedTameByUuid(source, p.getUUID(), d.uuid);
            if (orderOverride != null && loadedAfterTeleport != null) {
                applyMovementOverride(loadedAfterTeleport, orderOverride);
            }
            p.sendSystemMessage(Component.literal("Teleport: " + d.name + ".").withStyle(ChatFormatting.WHITE));
            return 1;
        }
        if (crossDimension) {
            if (orderOverride != null) {
                applyMovementOverride(ta, orderOverride);
            }
            if (!consumeHungerForCommandTeleport(p, d, ta)) return 0;
            UnloadedTpResult queued = queueImmediateChunkTeleport((ServerLevel) ta.level(), ta.blockPosition(), d, new SpawnTarget(p.serverLevel(), p.position(), p.getYRot(), p.getXRot()), true, false);
            if (!queued.success) return error(p, "Failed to queue cross-dimension tame teleport: " + queued.error);
            return 1;
        }
        if (!consumeHungerForCommandTeleport(p, d, ta)) return 0;
        teleportTameToPlayer(ta, p);
        TamableAnimal loadedAfterTeleport = findLoadedOwnedTameByUuid(source, p.getUUID(), d.uuid);
        if (orderOverride != null && loadedAfterTeleport != null) {
            applyMovementOverride(loadedAfterTeleport, orderOverride);
        }
        p.sendSystemMessage(Component.literal("Teleported " + d.name + (payment.xpSpent > 0 ? " (-" + payment.xpSpent + " XP points" : "") + (crossDimension ? ", cross-dimension" : "") + (payment.xpSpent > 0 ? ")." : ".")));
        return 1;
    }

