    private static int adminPlayerReincarnateBatch(CommandSourceStack source, String ownerName, List<TameData> requested, String label) {
        if (requested.isEmpty()) {
            return adminError(source, "No loaded reincarnation-eligible tames found for " + ownerName + " " + label + ".");
        }
        int totalLevelsRestored = 0;
        int restored = 0;
        List<String> failed = new ArrayList<>();
        for (TameData data : requested) {
            LivingEntity tame = findLoadedLivingTameByIdentity(source.getServer(), data.uuid, data.tlId);
            if (tame == null || !tame.isAlive() || !TameEntityAdapter.isTame(tame)) {
                continue;
            }
            int restoredLevels = Math.max(0, data.savedLevel - data.level);
            if (LevelSystem.restoreHighestProgressWithoutXpCost(tame, data)) {
                restored++;
                totalLevelsRestored += restoredLevels;
            } else {
                failed.add(tameDisplayName(data) + " (failed to restore saved progress)");
            }
        }
        if (restored <= 0) {
            StringBuilder message = new StringBuilder("No tames were reincarnated for ").append(ownerName).append(".");
            if (!failed.isEmpty()) {
                message.append(" Failures: ").append(String.join("; ", failed)).append(".");
            }
            return adminError(source, message.toString());
        }
        final int restoredCount = restored;
        final int restoredLevelsTotal = totalLevelsRestored;
        source.sendSuccess(() -> Component.literal(
                "Admin reincarnated " + restoredCount + " tame(s) for " + ownerName + " (" + restoredLevelsTotal + " total level(s) restored, no cost)."
        ).withStyle(ChatFormatting.GREEN), true);
        if (!failed.isEmpty()) {
            source.sendFailure(Component.literal("Failures: " + String.join("; ", failed)).withStyle(ChatFormatting.RED));
        }
        return 1;
    }

    static int graveyard(CommandSourceStack source, int requestedLimit) {
        ServerPlayer player = source.getPlayer();
        List<TameData> dead = ownedDeadTames(player.getUUID());
        if (dead.isEmpty()) {
            return error(player, "Your graveyard is empty.");
        }
        dead.sort(respawnQueueComparator(player.getUUID()));
        int limit = Math.min(Math.max(1, requestedLimit), dead.size());
        player.sendSystemMessage(Component.literal(
                "---- Graveyard | order: " + respawnOrderLabel(player.getUUID()) + " | showing " + limit + "/" + dead.size() + " ----"
        ).withStyle(ChatFormatting.DARK_GRAY));
        for (int i = 0; i < limit; i++) {
            TameData data = dead.get(i);
            int reincarnationCost = data.hasSavedProgress ? LevelSystem.reincarnationXpCost(data) : 0;
            player.sendSystemMessage(Component.literal(
                    (i + 1) + ". " + tameDisplayName(data)
            ).withStyle(ChatFormatting.GRAY));
            String deathMessage = latestDeathMessage(data);
            if (deathMessage.isBlank()) {
                deathMessage = "unknown";
            }
            player.sendSystemMessage(Component.literal(
                    deathMessage
                            + " (" + formatDeathTime(data.deadUnixMillis) + ") "
                            + reincarnationCost + " xp "
                            + graveyardLevelArrow(data)
            ).withStyle(ChatFormatting.DARK_RED));
        }
        return 1;
    }

    private static String graveyardLevelArrow(TameData data) {
        if (data == null) {
            return "[1]";
        }
        int fromLevel = Math.max(1, data.level);
        int toLevel = data.hasSavedProgress ? Math.max(fromLevel, data.savedLevel) : fromLevel;
        if (toLevel == fromLevel) {
            return "[" + fromLevel + "]";
        }
        return "[" + fromLevel + " -> " + toLevel + "]";
    }

    private static int adminPlayerRespawnDeadBatch(CommandSourceStack source, UUID ownerId, List<TameData> candidates, ReviveMode mode, String label, boolean reincarnateAfter) {
        if (source == null || ownerId == null || candidates == null || candidates.isEmpty()) {
            return 0;
        }
        String ownerName = resolveKnownOwnerName(source.getServer(), ownerId, ownerId.toString());
        ServerPlayer ownerPlayer = source.getServer() == null ? null : source.getServer().getPlayerList().getPlayer(ownerId);
        int success = 0;
        int failed = 0;
        int reincarnated = 0;
        List<String> respawnedNames = new ArrayList<>();
        List<String> failReasons = new ArrayList<>();
        List<String> unaffordable = new ArrayList<>();

        for (TameData data : candidates) {
            if (data == null || data.uuid == null) {
                failed++;
                failReasons.add("unknown (invalid registry entry)");
                continue;
            }
            if (isDuelLocked(data)) {
                failed++;
                failReasons.add(tameDisplayName(data) + " (active duel or duel session)");
                continue;
            }
            if (!isDeadEntry(data.uuid)) {
                continue;
            }
            if (findLoadedOwnedTameByUuid(source, ownerId, data.uuid) != null) {
                failed++;
                failReasons.add(data.name + " (already loaded)");
                continue;
            }
            SpawnTarget target = resolveAdminPlayerRespawnTarget(source, ownerId, data, mode);
            if (target == null || target.level == null) {
                failed++;
                failReasons.add(data.name + " (invalid target dimension)");
                continue;
            }
            RespawnResult result = respawnDeadTameAt(source, data, target.level, target.pos, target.yRot, target.xRot);
            if (!result.success) {
                failed++;
                failReasons.add(data.name + " (" + result.error + ")");
                continue;
            }
            if (isBedRespawnTarget(target)) applyBedRespawnMovement(source.getServer(), data);
            if (reincarnateAfter) {
                LivingEntity respawned = findLoadedLivingTameByIdentity(source.getServer(), data.uuid, data.tlId);
                if (respawned != null && respawned.isAlive() && data.hasSavedProgress && data.level < data.savedLevel
                        && LevelSystem.restoreHighestProgressWithoutXpCost(respawned, data)) {
                    reincarnated++;
                }
            }
            success++;
            respawnedNames.add(tameDisplayName(data));
        }

        if (success <= 0) {
            StringBuilder message = new StringBuilder("No dead tames respawned for ").append(ownerName).append(".");
            if (!failReasons.isEmpty()) {
                message.append(" Reasons: ").append(String.join("; ", failReasons));
            }
            if (!unaffordable.isEmpty()) {
                message.append(" Could not afford: ").append(String.join("; ", unaffordable)).append(".");
            }
            return adminError(source, message.toString());
        }
        final String respawnedList = respawnedNames.isEmpty() ? "none" : String.join(", ", respawnedNames);
        source.sendSuccess(() -> Component.literal("Respawned: " + respawnedList + ".").withStyle(ChatFormatting.WHITE), true);
        if (failed > 0 && !failReasons.isEmpty()) {
            source.sendFailure(Component.literal("Respawn failed for " + failed + ": " + String.join("; ", failReasons)).withStyle(ChatFormatting.RED));
        }
        return 1;
    }

    private static int respawnDeadBatch(CommandSourceStack source, ServerPlayer player, List<TameData> candidates, ReviveMode mode, String label, boolean reincarnateAfter) {
        if (source == null || player == null || candidates == null || candidates.isEmpty()) return 0;
        int success = 0;
        int failed = 0;
        int reincarnated = 0;
        List<String> respawnedNames = new ArrayList<>();
        List<String> failReasons = new ArrayList<>();
        List<String> unaffordable = new ArrayList<>();
        List<String> diedTodayNames = new ArrayList<>();
        int ariseUses = mode == ReviveMode.ARISE ? ariseUsesToday(player) : 0;

        for (TameData data : candidates) {
            if (data == null || data.uuid == null) {
                failed++;
                failReasons.add("unknown (invalid registry entry)");
                continue;
            }
            if (isDuelLocked(data)) {
                failed++;
                failReasons.add(tameDisplayName(data) + " (active duel or duel session)");
                continue;
            }
            if (!isDeadEntry(data.uuid)) {
                continue;
            }
            if (mode == ReviveMode.RESPAWN && diedOnCurrentGameDay(source.getServer(), data)) {
                failed++;
                diedTodayNames.add(data.name == null || data.name.isBlank() ? "unknown" : data.name);
                continue;
            }
            if (findLoadedOwnedTameByUuid(source, player.getUUID(), data.uuid) != null) {
                failed++;
                failReasons.add(data.name + " (already loaded)");
                continue;
            }
            int xpCost = reviveXpCost(data, mode);
            int approvedItemCost = reviveApprovedItemCost(data, mode);
            int totemCost = 1;
            if (mode == ReviveMode.ARISE) {
                xpCost = applyAriseDailyMultiplier(xpCost, ariseUses);
                approvedItemCost = applyAriseDailyMultiplier(approvedItemCost, ariseUses);
                totemCost = applyAriseDailyMultiplier(totemCost, ariseUses);
            }
            if (reincarnateAfter && data.hasSavedProgress && data.level < data.savedLevel) {
                xpCost += LevelSystem.reincarnationXpCost(data);
                approvedItemCost += Math.max(1, data.savedLevel - data.level);
            }
            PaymentResult preview = previewPayment(player, xpCost, approvedItemCost, totemCost, true, reincarnateAfter ? "respawn reincarnation" : (mode == ReviveMode.ARISE ? "arise" : "respawn"));
            if (!preview.success) {
                failed++;
                unaffordable.add(pricedTameLabel(data, paymentPriceLabel(xpCost, approvedItemCost, totemCost, true)));
                continue;
            }
            SpawnTarget target = resolveRespawnTarget(source, player, data, mode.toMe);
            if (target.level == null) {
                failed++;
                failReasons.add(data.name + " (invalid target dimension)");
                continue;
            }
            RespawnResult result = respawnDeadTameAt(source, data, target.level, target.pos, target.yRot, target.xRot);
            if (!result.success) {
                failed++;
                failReasons.add(data.name + " (" + result.error + ")");
                continue;
            }
            if (isBedRespawnTarget(target)) applyBedRespawnMovement(source.getServer(), data);
            PaymentResult payment = tryConsumePayment(player, xpCost, approvedItemCost, totemCost, true, reincarnateAfter ? "respawn reincarnation" : (mode == ReviveMode.ARISE ? "arise" : "respawn"));
            if (!payment.success) {
                failed++;
                failReasons.add(data.name + " (" + payment.error + ")");
                continue;
            }
            if (reincarnateAfter) {
                LivingEntity respawned = findLoadedLivingTameByIdentity(source.getServer(), data.uuid, data.tlId);
                if (respawned != null && respawned.isAlive() && data.hasSavedProgress && data.level < data.savedLevel
                        && LevelSystem.restoreHighestProgressWithoutXpCost(respawned, data)) {
                    reincarnated++;
                }
            }
            success++;
            if (mode == ReviveMode.ARISE) {
                recordAriseUse(player);
                if (ariseUses < Integer.MAX_VALUE) {
                    ariseUses++;
                }
            }
            respawnedNames.add(tameDisplayName(data));
        }

        if (!diedTodayNames.isEmpty()) {
            failReasons.add(String.join(", ", diedTodayNames)
                    + " died today; use arise(5xPrice) or wait until tomorrow.");
        }

        if (success <= 0) {
            StringBuilder message = new StringBuilder("No dead tames respawned.");
            if (!unaffordable.isEmpty()) {
                message.append(" Could not afford: ").append(String.join("; ", unaffordable)).append(".");
            }
            if (!failReasons.isEmpty()) {
                message.append(" Reasons: ").append(String.join("; ", failReasons));
            }
            return error(player, message.toString());
        }
        String respawnMessage = success > 1
                ? "Respawned " + success + " tames."
                : "Respawned: " + respawnedNames.get(0) + ".";
        player.sendSystemMessage(Component.literal(respawnMessage).withStyle(ChatFormatting.WHITE));
        sendAffordabilityFailures(player, reincarnateAfter ? "Could not afford respawn reincarnation for" : "Could not afford respawn for", unaffordable);
        if (failed > 0 && !failReasons.isEmpty()) {
            player.sendSystemMessage(Component.literal("Respawn failed for " + failed + ": " + String.join("; ", failReasons)).withStyle(ChatFormatting.RED));
        }
        return 1;
    }

    private record SpawnTarget(ServerLevel level, Vec3 pos, float yRot, float xRot) {}
    private record ArenaSpawnSet(String arenaName, SpawnTarget spawnA, SpawnTarget spawnB, SpawnTarget waitingA, SpawnTarget waitingB, boolean hideTames) {}

    private static SpawnTarget resolveRespawnTarget(CommandSourceStack source, ServerPlayer player, TameData data, boolean toMe) {
        if (toMe || data == null) {
            return new SpawnTarget(source.getLevel(), source.getPosition(), source.getRotation().y, source.getRotation().x);
        }
        SpawnTarget petBedTarget = resolveAutomaticRespawnBedTarget(source.getServer(), data);
        if (petBedTarget != null) {
            return petBedTarget;
        }
        SpawnTarget queuedBedTarget = resolveBedTargetFromDiQueue(source, data);
        if (queuedBedTarget != null) {
            return queuedBedTarget;
        }
        SpawnTarget ownerBedTarget = resolveOwnerBedTarget(source, player);
        if (ownerBedTarget != null) {
            return ownerBedTarget;
        }
        // No tame bed and no owner bed -> force respawn at player position.
        return new SpawnTarget(source.getLevel(), source.getPosition(), source.getRotation().y, source.getRotation().x);
    }

    private static SpawnTarget resolveAdminPlayerRespawnTarget(CommandSourceStack source, UUID ownerId, TameData data, ReviveMode mode) {
        if (source == null || source.getServer() == null) {
            return null;
        }
        if (mode == null) {
            mode = ReviveMode.RESPAWN;
        }
        ServerPlayer owner = ownerId == null ? null : source.getServer().getPlayerList().getPlayer(ownerId);
        if (mode.toMe) {
            if (owner == null) {
                return null;
            }
            return new SpawnTarget(owner.serverLevel(), owner.position(), owner.getYRot(), owner.getXRot());
        }
        if (data != null && data.hasPetBed && data.petBedDimension != null && !data.petBedDimension.isBlank()) {
            ResourceLocation bedId = ResourceLocation.tryParse(data.petBedDimension);
            if (bedId != null) {
                ServerLevel bedLevel = source.getServer().getLevel(ResourceKey.create(Registries.DIMENSION, bedId));
                if (bedLevel != null) {
                    return new SpawnTarget(bedLevel, new Vec3(data.petBedX + 0.5D, data.petBedY + 1.0D, data.petBedZ + 0.5D), 0.0F, 0.0F);
                }
            }
        }
        SpawnTarget diQueueTarget = resolveBedTargetFromDiQueue(source, data);
        if (diQueueTarget != null) {
            return diQueueTarget;
        }
        SpawnTarget ownerBedTarget = resolveOwnerBedTarget(source.getServer(), ownerId);
        if (ownerBedTarget != null) {
            return ownerBedTarget;
        }
        if (owner != null) {
            return new SpawnTarget(owner.serverLevel(), owner.position(), owner.getYRot(), owner.getXRot());
        }
        return new SpawnTarget(source.getLevel(), source.getPosition(), source.getRotation().y, source.getRotation().x);
    }

    private static SpawnTarget resolveOwnerBedTarget(CommandSourceStack source, ServerPlayer player) {
        if (source == null || source.getServer() == null || player == null) {
            return null;
        }
        return resolveOwnerBedTarget(source.getServer(), player.getUUID());
    }

    private static SpawnTarget resolveOwnerBedTarget(MinecraftServer server, UUID ownerUuid) {
        if (server == null || ownerUuid == null) {
            return null;
        }
        ServerPlayer player = server.getPlayerList().getPlayer(ownerUuid);
        if (player == null) {
            return null;
        }
        BlockPos respawnPos = player.getRespawnPosition();
        if (respawnPos == null) {
            return null;
        }
        ServerLevel respawnLevel = server.getLevel(player.getRespawnDimension());
        if (respawnLevel == null) {
            return null;
        }
        return new SpawnTarget(
                respawnLevel,
                new Vec3(respawnPos.getX() + 0.5D, respawnPos.getY(), respawnPos.getZ() + 0.5D),
                player.getRespawnAngle(),
                0.0F
        );
    }

    private static SpawnTarget resolveBedTargetFromDiQueue(CommandSourceStack source, TameData data) {
        if (source == null || source.getServer() == null || data == null || data.uuid == null) {
            return null;
        }
        DIWorldData worldData = DIWorldData.get(source.getLevel());
        if (worldData == null) {
            return null;
        }
        for (com.github.alexthe668.domesticationinnovation.server.misc.RespawnRequest request : worldData.getRespawnRequestsSnapshot()) {
            if (request == null || !matchesRespawnRequestIdentity(request, data)) {
                continue;
            }
            ResourceLocation dimId = ResourceLocation.tryParse(request.getDimension());
            if (dimId == null) {
                continue;
            }
            ServerLevel bedLevel = source.getServer().getLevel(ResourceKey.create(Registries.DIMENSION, dimId));
            if (bedLevel == null) {
                continue;
            }
            BlockPos bedPos = request.getBedPosition();
            return new SpawnTarget(bedLevel, new Vec3(bedPos.getX() + 0.5D, bedPos.getY(), bedPos.getZ() + 0.5D), 0.0F, 0.0F);
        }
        return null;
    }

    private record RespawnResult(boolean success, String error) {
        static RespawnResult ok() {
            return new RespawnResult(true, "");
        }
        static RespawnResult fail(String error) {
            return new RespawnResult(false, error == null ? "unknown error" : error);
        }
    }

    private record AdminRespawnEntry(TameData data, TameDeathRecord deadRecord) {
    }

    private static RespawnResult respawnDeadTameAt(CommandSourceStack source, TameData data, ServerLevel level, Vec3 pos, float yRot, float xRot) {
        if (com.github.alexthe668.domesticationinnovation.server.tameslevel.compat.BewereagerCompat.isLocked(data)) return RespawnResult.fail("hostile Bewereager cannot be controlled");
        if (data != null && data.horseType) return RespawnResult.fail("horse-type tames cannot be rebuilt or respawned");
        if (data == null || level == null || pos == null) return RespawnResult.fail("invalid context");

        String typeId = recoverEntityTypeId(data);
        if (typeId.isBlank()) return RespawnResult.fail("missing saved entity type");

        ResourceLocation id = ResourceLocation.tryParse(typeId);
        if (id == null) return RespawnResult.fail("invalid entity type '" + typeId + "'");

        EntityType<?> entityType = ForgeRegistries.ENTITY_TYPES.getValue(id);
        if (entityType == null) return RespawnResult.fail("unknown entity type '" + typeId + "'");

        TameSpawnEvents.beginTameReconstruction();
        try {
            Entity spawned = entityType.create(level);
            if (!(spawned instanceof LivingEntity respawned)
                    || (!(respawned instanceof TamableAnimal) && !(respawned instanceof ModifedToBeTameable))) {
                return RespawnResult.fail("stored type is not tamable");
            }

        // Loading a tame snapshot can synchronously fire tame-related Forge events. The
        // freshly-created entity still has a temporary UUID at this point unless we replace
        // it first. Such an event used to register/rebind the existing registry row to that
        // temporary UUID, which produced throwaway class notifications and left ranked's
        // stable participant UUID invalid (so its scrubber pulled the tame from the pool).
        // Publish the canonical identity before any snapshot state is applied.
        respawned.setUUID(data.uuid);
        TameRegistry.register(data);
        TameRegistry.bindEntityToData(respawned, data);

            CompoundTag snapshot = data.entitySnapshot == null ? new CompoundTag() : data.entitySnapshot.copy();
            if (!snapshot.isEmpty()) {
                respawned.load(snapshot);
            }

        // Snapshot loading may contain an older entity UUID; canonical registry identity wins.
        respawned.setUUID(data.uuid);
        respawned.moveTo(pos.x, pos.y, pos.z, yRot, xRot);
        respawned.setDeltaMovement(0.0D, 0.0D, 0.0D);
        respawned.getPersistentData().putBoolean(ADMIN_CLONE_SILENT_TAG, true);
        enforceRecoveredTameOwner(respawned, data.ownerUUID);

        if (!level.addFreshEntity(respawned)) {
            return RespawnResult.fail("spawn failed (UUID conflict or invalid state)");
        }
        clearAdminCloneTags(respawned);

        boolean normalized = LevelSystem.reapplyTypeBasePlusBonuses(respawned, data);
        if (!normalized) {
            LevelSystem.updateTameName(respawned, data);
            respawned.setHealth(respawned.getMaxHealth());
        }
        prepareAutoReincarnationOnRespawn(level.getServer(), data);
        finalizeRecoveredLivingState(respawned, data);
        restoreRecoveredAppearance(respawned, snapshot);
        TameRegistry.bindEntityToData(respawned, data);
        clearMatchingDiBedRespawnRequests(source, data);
        TameRegistry.register(data);
        TameRegistry.markDirty();
        return RespawnResult.ok();
        } finally {
            TameSpawnEvents.endTameReconstruction();
        }
    }

    public static boolean respawnDeadTameForDuel(MinecraftServer server, UUID tameUuid) {
        if (server == null || tameUuid == null) {
            return false;
        }
        TameData data = TameRegistry.get(tameUuid);
        if (data == null) {
            data = TameRegistry.getByTlId(tameUuid);
        }
        if (data == null || !data.dead) {
            return false;
        }
        SpawnTarget target = resolveDuelRespawnTarget(server, data);
        if (target == null || target.level == null || target.pos == null) {
            return false;
        }
        RespawnResult result = respawnDeadTameAtServer(data, target.level, target.pos, target.yRot, target.xRot);
        if (!result.success) {
            return false;
        }
        clearMatchingDiBedRespawnRequests(server, data);
        TameRegistry.markDirty();
        return true;
    }

    public static boolean respawnDeadTameNextToOwner(MinecraftServer server, UUID tameUuid) {
        if (server == null || tameUuid == null) {
            return false;
        }
        TameData data = TameRegistry.get(tameUuid);
        if (data == null) {
            data = TameRegistry.getByTlId(tameUuid);
        }
        if (data == null || !data.dead || data.ownerUUID == null) {
            return false;
        }
        ServerPlayer owner = server.getPlayerList().getPlayer(data.ownerUUID);
        if (owner == null) {
            return false;
        }
        Vec3 spawnPos = owner.position().add(1.5D, 0.0D, 0.0D);
        RespawnResult result = respawnDeadTameAtServer(data, owner.serverLevel(), spawnPos, owner.getYRot(), owner.getXRot());
        if (!result.success) {
            return false;
        }
        clearMatchingDiBedRespawnRequests(server, data);
        TameRegistry.markDirty();
        return true;
    }

    public static boolean resetDuelCombatState(MinecraftServer server, UUID tameUuid) {
        if (server == null || tameUuid == null) {
            return false;
        }
        TameData data = TameRegistry.get(tameUuid);
        if (data == null) {
            return false;
        }
        boolean changed = false;
        if (data.dead) {
            changed = respawnDeadTameForDuel(server, tameUuid);
            data = TameRegistry.get(tameUuid);
            if (data == null) {
                return changed;
            }
        }
        data.cooldowns.clear();
        changed = true;

        LivingEntity loaded = findLoadedLivingTameByIdentity(server, data.uuid, data.tlId);
        if (loaded != null && loaded.isAlive()) {
            loaded.removeAllEffects();
            loaded.setSecondsOnFire(0);
            loaded.setHealth(loaded.getMaxHealth());
            TameEntityAdapter.setTarget(loaded, null);
            if (loaded instanceof net.minecraft.world.entity.Mob mob) {
                mob.getNavigation().stop();
            }
            loaded.setLastHurtByMob(null);
            loaded.setLastHurtMob(null);
            CompoundTag refreshed = new CompoundTag();
            loaded.save(refreshed);
            data.entitySnapshot = refreshed;
        }
        TameRegistry.markDirty();
        return changed;
    }

    public static boolean restoreDuelParticipantSnapshot(MinecraftServer server, CompoundTag tameSnapshotTag) {
        if (server == null || tameSnapshotTag == null || tameSnapshotTag.isEmpty()) {
            return false;
        }
        TameSpawnEvents.beginTameReconstruction();
        try {
        TameData snapshot = TameData.fromTag(tameSnapshotTag.copy());
        if (snapshot.uuid == null) {
            return false;
        }
        SpawnTarget target = spawnTargetFromSnapshot(server, snapshot);
        if (target == null || target.level == null || target.pos == null) {
            return false;
        }
        TameData persisted = TameRegistry.get(snapshot.uuid);
        if (persisted == null && snapshot.tlId != null) {
            persisted = TameRegistry.getByTlId(snapshot.tlId);
        }
        // A duel recovery can replace the entity and rebind the persisted tame to a new
        // UUID while the pre-duel snapshot still contains the old UUID. Registering that
        // stale snapshot would create a second registry entry; addToIndexes would then see
        // the shared TL-ID as a collision and assign the stale entry a new TL-ID, leaving an
        // unloaded same-name duplicate behind. Keep the stable registry identity canonical
        // before the snapshot is registered or used to rebuild the entity.
        if (persisted != null) {
            snapshot.uuid = persisted.uuid;
            snapshot.tlId = persisted.ensureTlId();
        }
        copyPersistentDuelStats(persisted, snapshot);
        snapshot.dead = false;
        snapshot.stored = false;
        // Ranked participants return home after the battle and must remain there.
        // This also makes rebuilt participants inherit the same state as /tames tphome.
        snapshot.movementOrder = 1;
        TameRegistry.register(snapshot);
        cancelPendingImmediateChunkTeleport(server, snapshot);
        UUID returnTicket = snapshot.tlId != null ? snapshot.tlId : snapshot.uuid;
        BlockPos returnPos = BlockPos.containing(target.pos);
        loadChunksAround(target.level, returnTicket, returnPos, true);
        try {
            ChunkPos returnChunk = new ChunkPos(returnPos);
            for (int dx = -1; dx <= 1; dx++) {
                for (int dz = -1; dz <= 1; dz++) {
                    target.level.getChunk(returnChunk.x + dx, returnChunk.z + dz);
                }
            }

            LivingEntity loaded = findLoadedLivingTameByIdentity(server, snapshot.uuid, snapshot.tlId);
            if (loaded != null && loaded.isAlive()) {
                teleportLivingTameToLocation(loaded, target, true);
                // Cross-dimension transfer replaces the entity instance, so always reacquire it.
                LivingEntity restored = findLoadedLivingTameByIdentity(server, snapshot.uuid, snapshot.tlId);
                if (restored == null || !restored.isAlive()) {
                    return false;
                }
                if (restored instanceof TamableAnimal tamable) {
                    refreshLoadedTameStatsAfterRebuild(tamable, snapshot, true);
                    finalizeRespawnState(tamable, snapshot);
                    TameGoalInstaller.installIfMissing(tamable);
                } else {
                    restored.removeAllEffects();
                    restored.setSecondsOnFire(0);
                    restored.setHealth(restored.getMaxHealth());
                    TameEntityAdapter.setTarget(restored, null);
                    if (restored instanceof net.minecraft.world.entity.Mob mob) {
                        mob.getNavigation().stop();
                    }
                }
                applyLivingMovementOverride(restored, snapshot, MovementOrder.SIT);
                TameData.syncTlIdToEntity(restored, snapshot.tlId);
                CompoundTag refreshed = new CompoundTag();
                restored.save(refreshed);
                snapshot.entitySnapshot = refreshed;
                TameRegistry.register(snapshot);
                return true;
            }
            if (loaded != null) {
                loaded.remove(Entity.RemovalReason.DISCARDED);
                loaded.discard();
            }
            RespawnResult result;
            beginSuppressedUnloadedTeleportMessages(snapshot.ownerUUID);
            try {
                result = respawnDeadTameAtServer(snapshot, target.level, target.pos, target.yRot, target.xRot);
            } finally {
                endSuppressedUnloadedTeleportMessages(snapshot.ownerUUID);
            }
            if (!result.success) {
                return false;
            }
            LivingEntity restored = findLoadedLivingTameByIdentity(server, snapshot.uuid, snapshot.tlId);
            if (restored != null) {
                applyLivingMovementOverride(restored, snapshot, MovementOrder.SIT);
                TameData.syncTlIdToEntity(restored, snapshot.tlId);
                if (restored instanceof TamableAnimal tamable) {
                    TameGoalInstaller.installIfMissing(tamable);
                }
            }
            return restored != null;
        } finally {
            loadChunksAround(target.level, returnTicket, returnPos, false);
        }
        } finally {
            TameSpawnEvents.endTameReconstruction();
        }
    }

    public static boolean ensureDuelParticipantRestored(MinecraftServer server, UUID participantId, CompoundTag tameSnapshotTag) {
        if (server == null || tameSnapshotTag == null || tameSnapshotTag.isEmpty()) {
            return participantId != null && resetDuelCombatState(server, participantId);
        }
        TameSpawnEvents.beginTameReconstruction();
        try {
        if (restoreDuelParticipantSnapshot(server, tameSnapshotTag.copy())) {
            return true;
        }
        TameData snapshot = TameData.fromTag(tameSnapshotTag.copy());
        if (snapshot == null || snapshot.uuid == null) {
            return participantId != null && resetDuelCombatState(server, participantId);
        }
        cancelPendingImmediateChunkTeleport(server, snapshot);
        LivingEntity loaded = findLoadedLivingTameByIdentity(server, snapshot.uuid, snapshot.tlId);
        if (loaded != null && loaded.isAlive()) {
            if (loaded instanceof TamableAnimal tamable) {
                refreshLoadedTameStatsAfterRebuild(tamable, snapshot, true);
                finalizeRespawnState(tamable, snapshot);
                TameGoalInstaller.installIfMissing(tamable);
            } else {
                loaded.removeAllEffects();
                loaded.setSecondsOnFire(0);
                loaded.setHealth(loaded.getMaxHealth());
                TameEntityAdapter.setTarget(loaded, null);
            }
            applyLivingMovementOverride(loaded, snapshot, MovementOrder.SIT);
            TameData.syncTlIdToEntity(loaded, snapshot.tlId);
            return true;
        }
        if (loaded != null) {
            loaded.remove(Entity.RemovalReason.DISCARDED);
            loaded.discard();
        }
        SpawnTarget target = spawnTargetFromSnapshot(server, snapshot);
        if (target != null && target.level != null && target.pos != null) {
            ServerPlayer owner = snapshot.ownerUUID == null ? null : server.getPlayerList().getPlayer(snapshot.ownerUUID);
            if (owner != null) {
                RecoverResult recovered = recoverPetEntityAtLocation(owner, target, snapshot);
                if (recovered.entity != null) {
                    return true;
                }
            }
            RespawnResult result = respawnDeadTameAtServer(snapshot, target.level, target.pos, target.yRot, target.xRot);
            if (result.success) {
                LivingEntity restored = findLoadedLivingTameByIdentity(server, snapshot.uuid, snapshot.tlId);
                if (restored != null) {
                    TameData.syncTlIdToEntity(restored, snapshot.tlId);
                    applyLivingMovementOverride(restored, snapshot, MovementOrder.SIT);
                    if (restored instanceof TamableAnimal tamable) {
                        TameGoalInstaller.installIfMissing(tamable);
                    }
                }
                return true;
            }
        }
        return participantId != null && resetDuelCombatState(server, participantId);
        } finally {
            TameSpawnEvents.endTameReconstruction();
        }
    }

    public static boolean restoreDuelPlayerSnapshot(MinecraftServer server, UUID playerUuid, CompoundTag playerSnapshot) {
        if (server == null || playerUuid == null || playerSnapshot == null || playerSnapshot.isEmpty()) {
            return false;
        }
        ServerPlayer player = server.getPlayerList().getPlayer(playerUuid);
        if (player == null) {
            return false;
        }

        // Only vanilla armor is protected from duel wear. Loading the complete player NBT here also
        // rewinds Forge capabilities such as Curios/Artifacts and can eject their equipped stacks.
        List<ItemStack> armor = new ArrayList<>(List.of(
                ItemStack.EMPTY, ItemStack.EMPTY, ItemStack.EMPTY, ItemStack.EMPTY));
        ListTag inventory = playerSnapshot.getList("Inventory", Tag.TAG_COMPOUND);
        for (int i = 0; i < inventory.size(); i++) {
            CompoundTag entry = inventory.getCompound(i);
            int armorIndex = entry.getByte("Slot") - 100;
            if (armorIndex >= 0 && armorIndex < armor.size()) {
                armor.set(armorIndex, ItemStack.of(entry));
            }
        }
        for (int i = 0; i < armor.size(); i++) {
            player.getInventory().armor.set(i, armor.get(i));
        }
        player.removeAllEffects();
        player.setSecondsOnFire(0);
        player.setHealth(player.getMaxHealth());
        player.invulnerableTime = Math.max(player.invulnerableTime, 20);
        player.hurtMarked = true;
        player.containerMenu.broadcastChanges();
        player.inventoryMenu.broadcastChanges();
        return true;
    }

    public static void copyPersistentDuelStats(TameData from, TameData into) {
        TameDuelSnapshots.copyPersistentStats(from, into);
    }

    private static SpawnTarget resolveDuelRespawnTarget(MinecraftServer server, TameData data) {
        if (server == null || data == null) {
            return null;
        }
        if (data.hasPetBed && data.petBedDimension != null && !data.petBedDimension.isBlank()) {
            ResourceLocation bedId = ResourceLocation.tryParse(data.petBedDimension);
            if (bedId != null) {
                ServerLevel bedLevel = server.getLevel(ResourceKey.create(Registries.DIMENSION, bedId));
                if (bedLevel != null) {
                    return new SpawnTarget(bedLevel, new Vec3(data.petBedX + 0.5D, data.petBedY, data.petBedZ + 0.5D), 0.0F, 0.0F);
                }
            }
        }
        if (data.ownerUUID != null) {
            ServerPlayer owner = server.getPlayerList().getPlayer(data.ownerUUID);
            if (owner != null) {
                return new SpawnTarget(owner.serverLevel(), owner.position(), owner.getYRot(), owner.getXRot());
            }
        }
        if (data.lastKnownDimension != null && !data.lastKnownDimension.isBlank()) {
            ResourceLocation lastDim = ResourceLocation.tryParse(data.lastKnownDimension);
            if (lastDim != null) {
                ServerLevel lastLevel = server.getLevel(ResourceKey.create(Registries.DIMENSION, lastDim));
                if (lastLevel != null) {
                    return new SpawnTarget(lastLevel, new Vec3(data.lastKnownX + 0.5D, data.lastKnownY, data.lastKnownZ + 0.5D), 0.0F, 0.0F);
                }
            }
        }
        ServerLevel overworld = server.overworld();
        Vec3 spawnPos = Vec3.atCenterOf(overworld.getSharedSpawnPos());
        return new SpawnTarget(overworld, spawnPos, 0.0F, 0.0F);
    }

    private static RespawnResult respawnDeadTameAtServer(TameData data, ServerLevel level, Vec3 pos, float yRot, float xRot) {
        if (com.github.alexthe668.domesticationinnovation.server.tameslevel.compat.BewereagerCompat.isLocked(data)) return RespawnResult.fail("hostile Bewereager cannot be controlled");
        if (data != null && data.horseType) return RespawnResult.fail("horse-type tames cannot be rebuilt or respawned");
        if (data == null || level == null || pos == null) return RespawnResult.fail("invalid context");

        String typeId = recoverEntityTypeId(data);
        if (typeId.isBlank()) return RespawnResult.fail("missing saved entity type");

        ResourceLocation id = ResourceLocation.tryParse(typeId);
        if (id == null) return RespawnResult.fail("invalid entity type '" + typeId + "'");

        EntityType<?> entityType = ForgeRegistries.ENTITY_TYPES.getValue(id);
        if (entityType == null) return RespawnResult.fail("unknown entity type '" + typeId + "'");

        TameSpawnEvents.beginTameReconstruction();
        try {
            Entity spawned = entityType.create(level);
            if (!(spawned instanceof LivingEntity respawned)
                    || (!(respawned instanceof TamableAnimal) && !(respawned instanceof ModifedToBeTameable))) {
                return RespawnResult.fail("stored type is not tamable");
            }

            // Snapshot loading can fire tame events, so expose the canonical registry
            // identity before applying any saved entity state.
            respawned.setUUID(data.uuid);
            TameRegistry.register(data);
            TameRegistry.bindEntityToData(respawned, data);

            CompoundTag snapshot = data.entitySnapshot == null ? new CompoundTag() : data.entitySnapshot.copy();
            if (!snapshot.isEmpty()) {
                respawned.load(snapshot);
            }

            respawned.setUUID(data.uuid);
            respawned.moveTo(pos.x, pos.y, pos.z, yRot, xRot);
            respawned.setDeltaMovement(0.0D, 0.0D, 0.0D);
            enforceRecoveredTameOwner(respawned, data.ownerUUID);
        // addFreshEntity fires EntityJoinLevelEvent synchronously. Bind the stable tame
        // identity first so the spawn handler resolves this rebuilt duel participant to
        // its existing registry row instead of briefly registering it as a new tame and
        // rolling/notifying a throwaway class.
            TameRegistry.bindEntityToData(respawned, data);

            if (!level.addFreshEntity(respawned)) {
                return RespawnResult.fail("spawn failed (UUID conflict or invalid state)");
            }
            clearAdminCloneTags(respawned);

            LevelSystem.reapplyTypeBasePlusBonuses(respawned, data);
            respawned.setHealth(respawned.getMaxHealth());
            prepareAutoReincarnationOnRespawn(level.getServer(), data);
            finalizeRecoveredLivingState(respawned, data);
            restoreRecoveredAppearance(respawned, snapshot);
            TameRegistry.register(data);
            return RespawnResult.ok();
        } finally {
            TameSpawnEvents.endTameReconstruction();
        }
    }

    private static SpawnTarget spawnTargetFromSnapshot(MinecraftServer server, TameData data) {
        if (server == null || data == null) {
            return null;
        }
        ServerLevel level = null;
        if (data.lastKnownDimension != null && !data.lastKnownDimension.isBlank()) {
            ResourceLocation dimId = ResourceLocation.tryParse(data.lastKnownDimension);
            if (dimId != null) {
                level = server.getLevel(ResourceKey.create(Registries.DIMENSION, dimId));
            }
        }
        if (level == null) {
            level = server.overworld();
        }
        Vec3 pos = new Vec3(data.lastKnownX + 0.5D, data.lastKnownY, data.lastKnownZ + 0.5D);
        float yRot = 0.0F;
        float xRot = 0.0F;
        CompoundTag entitySnapshot = data.entitySnapshot;
        if (entitySnapshot != null && entitySnapshot.contains("Pos", Tag.TAG_LIST)) {
            ListTag posList = entitySnapshot.getList("Pos", Tag.TAG_DOUBLE);
            if (posList.size() >= 3) {
                pos = new Vec3(posList.getDouble(0), posList.getDouble(1), posList.getDouble(2));
            }
        }
        if (entitySnapshot != null && entitySnapshot.contains("Rotation", Tag.TAG_LIST)) {
            ListTag rotList = entitySnapshot.getList("Rotation", Tag.TAG_FLOAT);
            if (rotList.size() >= 2) {
                yRot = rotList.getFloat(0);
                xRot = rotList.getFloat(1);
            }
        }
        return new SpawnTarget(level, pos, yRot, xRot);
    }

    public static boolean respawnDeadTameAtBed(ServerLevel level, BlockPos bedPos, Direction facing, TameData data) {
        if (level == null || bedPos == null || data == null || data.uuid == null || !data.dead) {
            return false;
        }
        if (isDuelLocked(data)) {
            return false;
        }
        Vec3 spawnPos = Vec3.upFromBottomCenterOf(bedPos, 0.8F);
        float yRot = yawFromDirection(facing);
        RespawnResult result = respawnDeadTameAtServer(data, level, spawnPos, yRot, 0.0F);
        if (!result.success) {
            return false;
        }
        applyBedRespawnMovement(level.getServer(), data);
        return true;
    }

    private static boolean isBedRespawnTarget(SpawnTarget target) {
        if (target == null || target.level == null || target.pos == null) return false;
        BlockPos pos = BlockPos.containing(target.pos.x, target.pos.y - 0.5D, target.pos.z);
        return target.level.getBlockState(pos).getBlock() instanceof PetBedBlock;
    }

    private static void applyBedRespawnMovement(MinecraftServer server, TameData data) {
        if (server == null || data == null) return;
        LivingEntity respawned = findLoadedLivingTameByIdentity(server, data.uuid, data.tlId);
        if (respawned == null || !respawned.isAlive()) return;
        boolean deployGuardian = data.movementOrder == 3 && data.hasHome;
        String guardianDimension = data.homeDimension;
        int guardianX = data.homeX;
        int guardianY = data.homeY;
        int guardianZ = data.homeZ;
        applyLivingMovementOverride(respawned, data, MovementOrder.SIT);
        if (deployGuardian) {
            // Sitting normally clears the guardian anchor. Preserve it during
            // the short post-respawn recovery period, then redeploy after 5s.
            data.hasHome = true;
            data.homeDimension = guardianDimension;
            data.homeX = guardianX;
            data.homeY = guardianY;
            data.homeZ = guardianZ;
            ServerLevel overworld = server.overworld();
            long now = overworld == null ? server.getTickCount() : overworld.getGameTime();
            UUID ticket = data.ensureTlId();
            PENDING_GUARDIAN_RESPAWN_DEPLOYMENTS.put(ticket,
                    new PendingGuardianRespawnDeployment(data.uuid, data.tlId, now + 100L));
        }
        if (respawned instanceof TamableAnimal tamable) refreshRegistrySnapshotFor(tamable);
        else {
            CompoundTag snapshot = new CompoundTag();
            respawned.save(snapshot);
            data.entitySnapshot = snapshot;
        }
        TameRegistry.markDirty();
    }

    private static void processPendingGuardianRespawnDeployments(MinecraftServer server) {
        if (server == null || PENDING_GUARDIAN_RESPAWN_DEPLOYMENTS.isEmpty()) return;
        ServerLevel overworld = server.overworld();
        long now = overworld == null ? server.getTickCount() : overworld.getGameTime();
        Iterator<Map.Entry<UUID, PendingGuardianRespawnDeployment>> iterator = PENDING_GUARDIAN_RESPAWN_DEPLOYMENTS.entrySet().iterator();
        while (iterator.hasNext()) {
            PendingGuardianRespawnDeployment pending = iterator.next().getValue();
            if (pending == null || now < pending.dueTick) continue;
            TameData data = pending.tlId == null ? null : TameRegistry.getByTlId(pending.tlId);
            if (data == null && pending.tameUuid != null) data = TameRegistry.get(pending.tameUuid);
            if (data == null || data.dead || !data.hasHome || data.movementOrder != 1) {
                iterator.remove();
                continue;
            }
            LivingEntity tame = findLoadedLivingTameByIdentity(server, data.uuid, data.tlId);
            if (tame == null || !tame.isAlive()) continue;
            applyLivingMovementOverride(tame, data, MovementOrder.GUARDIAN);
            iterator.remove();
        }
    }

    private record PendingGuardianRespawnDeployment(UUID tameUuid, UUID tlId, long dueTick) {
    }

    private static float yawFromDirection(Direction direction) {
        if (direction == null) {
            return 0.0F;
        }
        return switch (direction) {
            case NORTH -> 180.0F;
            case EAST -> -90.0F;
            case SOUTH -> 0.0F;
            case WEST -> 90.0F;
            default -> 0.0F;
        };
    }

    public static void handleExternalRespawn(TamableAnimal tame) {
        if (tame == null) {
            return;
        }
        TameData data = TameRegistry.get(tame.getUUID());
        if (data == null) {
            return;
        }
        finalizeRespawnState(tame, data);
        TameRegistry.markDirty();
    }

    private static void finalizeRespawnState(TamableAnimal tame, TameData data) {
        if (tame == null || data == null) {
            return;
        }
        if (!Objects.equals(data.uuid, tame.getUUID())) {
            TameRegistry.rebindEntityUuid(data, tame.getUUID());
        }
        data.stored = false;
        logRebuildTrace("finalizeRespawnState.begin", data,
                "entityUuid=" + tame.getUUID() + " entityTlId=" + TameData.getTlId(tame) + " dim=" + tame.level().dimension().location());
        removeCompetingLoadedTameCopies(tame, data);
        TameRegistry.bindEntityToData(tame, data);
        applyLatestDeathSnapshotIfAvailable(tame, data);
        tame.stopRiding();
        if (tame.isVehicle()) {
            tame.ejectPassengers();
        }
        tame.removeAllEffects();
        tame.setHealth(tame.getMaxHealth());
        tame.hurtTime = 0;
        tame.deathTime = 0;
        tame.invulnerableTime = 0;
        tame.setSecondsOnFire(0);
        tame.setRemainingFireTicks(0);
        clearFrozenState(tame);
        tame.fallDistance = 0.0F;
        tame.setDeltaMovement(0.0D, 0.0D, 0.0D);
        tame.setTarget(null);
        tame.getNavigation().stop();
        tame.setNoGravity(false);
        tame.setNoAi(false);
        tame.setInSittingPose(false);
        TameGoalInstaller.installIfMissing(tame);
        if (data.hasHome) {
            // Respawns should preserve guardian mode when the tame died with a current guardian anchor.
            tame.setOrderedToSit(false);
            clearExternalWanderingState(tame, MovementOrder.GUARDIAN);
        }
        data.dead = false;
        data.deadGameTime = 0L;
        data.deadUnixMillis = 0L;
        data.deathDimension = "";
        data.deathX = 0;
        data.deathY = 0;
        data.deathZ = 0;
        data.lastActiveSurvivalDay = Long.MIN_VALUE;
        data.lastKnownDimension = tame.level().dimension().location().toString();
        data.lastKnownX = tame.blockPosition().getX();
        data.lastKnownY = tame.blockPosition().getY();
        data.lastKnownZ = tame.blockPosition().getZ();
        data.lastKnownGameTime = tame.level().getGameTime();
        CompoundTag refreshedSnapshot = new CompoundTag();
        TameRegistry.bindEntityToData(tame, data);
        tame.save(refreshedSnapshot);
        data.entitySnapshot = refreshedSnapshot;
        tame.getPersistentData().remove("TLLastClientRefreshQueued");
        queueClientReloadForTame(tame, true);
        logRebuildTrace("finalizeRespawnState.end", data,
                "entityUuid=" + tame.getUUID() + " entityTlId=" + TameData.getTlId(tame) + " dim=" + tame.level().dimension().location());
    }

    private static void clearFrozenState(TamableAnimal tame) {
        tame.setTicksFrozen(0);
        TameableUtils.setFrozenTimeTag(tame, 0);
        TameableUtils.setFrozenLevel(tame, 0);
    }

    private static void removeCompetingLoadedTameCopies(TamableAnimal keeper, TameData data) {
        if (keeper == null || data == null || keeper.level() == null || keeper.level().getServer() == null) {
            return;
        }
        UUID keeperUuid = keeper.getUUID();
        UUID keeperTlId = data.tlId;
        List<TamableAnimal> duplicates = new ArrayList<>();
        for (ServerLevel level : keeper.level().getServer().getAllLevels()) {
            for (Entity entity : level.getAllEntities()) {
                if (!(entity instanceof TamableAnimal other) || other == keeper) {
                    continue;
                }
                UUID otherTlId = TameData.getTlId(other);
                if (keeperUuid.equals(other.getUUID()) || (keeperTlId != null && keeperTlId.equals(otherTlId))) {
                    duplicates.add(other);
                }
            }
        }
        for (TamableAnimal duplicate : duplicates) {
            logDeleteTrace("removeCompetingLoadedTameCopies", data, duplicate,
                    "keeperUuid=" + keeperUuid + " keeperTlId=" + keeperTlId + " keeperDim=" + keeper.level().dimension().location());
            TameDuelManager.endDuelForTame(keeper.level().getServer(), duplicate.getUUID());
            forceRemoveLoadedTame(duplicate);
        }
    }

    private static void clearMatchingDiBedRespawnRequests(CommandSourceStack source, TameData data) {
        if (source == null || source.getServer() == null || data == null) return;
        DIWorldData worldData = DIWorldData.get(source.getLevel());
        if (worldData == null) return;
        if (data.uuid != null && worldData.removeRespawnRequestsForPet(data.uuid) > 0) return;
        if (data.tlId != null && worldData.removeRespawnRequestsForPet(data.tlId) > 0) return;

        if (!data.hasPetBed || data.petBedDimension == null || data.petBedDimension.isBlank()) return;
        ResourceLocation bedDim = ResourceLocation.tryParse(data.petBedDimension);
        if (bedDim == null) return;
        ServerLevel bedLevel = source.getServer().getLevel(ResourceKey.create(Registries.DIMENSION, bedDim));
        if (bedLevel == null) return;
        BlockPos bedPos = new BlockPos(data.petBedX, data.petBedY, data.petBedZ);
        String wantedType = recoverEntityTypeId(data);
        String wantedName = stripLevelPrefixes(data.name == null ? "" : data.name);
        List<com.github.alexthe668.domesticationinnovation.server.misc.RespawnRequest> requests =
                new ArrayList<>(worldData.getRespawnRequestsFor(bedLevel, bedPos));
        for (com.github.alexthe668.domesticationinnovation.server.misc.RespawnRequest request : requests) {
            if (request == null) continue;
            if (wantedType != null && !wantedType.isBlank()) {
                String reqType = request.getEntityTypeLoc();
                if (reqType == null || !reqType.equalsIgnoreCase(wantedType)) continue;
            }
            String reqName = stripLevelPrefixes(request.getNametag() == null ? "" : request.getNametag());
            if (!wantedName.isBlank() && !reqName.isBlank() && !wantedName.equalsIgnoreCase(reqName)) continue;
            worldData.removeRespawnRequest(request);
        }
    }

    private static void clearMatchingDiBedRespawnRequests(MinecraftServer server, TameData data) {
        if (server == null || data == null || (data.uuid == null && data.tlId == null)) {
            return;
        }
        for (ServerLevel level : server.getAllLevels()) {
            DIWorldData worldData = DIWorldData.get(level);
            if (worldData == null) {
                continue;
            }
            if (data.uuid != null) {
                worldData.removeRespawnRequestsForPet(data.uuid);
            }
            if (data.tlId != null) {
                worldData.removeRespawnRequestsForPet(data.tlId);
            }
        }
    }

    private static boolean matchesRespawnRequestIdentity(com.github.alexthe668.domesticationinnovation.server.misc.RespawnRequest request, TameData data) {
        if (request == null || data == null) {
            return false;
        }
        CompoundTag entityData = request.getEntityData();
        if (entityData == null) {
            return false;
        }
        if (data.tlId != null && entityData.hasUUID("TLID") && data.tlId.equals(entityData.getUUID("TLID"))) {
            return true;
        }
        UUID uuid = data.uuid;
        if (uuid == null) {
            return false;
        }
        if (entityData.hasUUID("TLRegistryUUID")) {
            return uuid.equals(entityData.getUUID("TLRegistryUUID"));
        }
        return entityData.contains("UUID", Tag.TAG_INT_ARRAY)
                && entityData.hasUUID("UUID")
                && uuid.equals(entityData.getUUID("UUID"));
    }

    private static RecoverResult recoverPetEntity(CommandSourceStack source, ServerPlayer p, TameData data) {
        if (com.github.alexthe668.domesticationinnovation.server.tameslevel.compat.BewereagerCompat.isLocked(data)) return RecoverResult.fail("hostile Bewereager cannot be controlled");
        if (data != null && data.horseType) return RecoverResult.fail("horse-type tames cannot be recovered");
        if (p == null || data == null) return RecoverResult.fail("invalid context");
        if (data.uuid == null) return RecoverResult.fail("missing tame UUID");
        clearGuardianAnchor(data);
        if (isDeadEntry(data.uuid)) return RecoverResult.fail("tame is marked dead");
        String logicalKey = logicalTameKey(data);
        if (!logicalKey.isBlank() && hasLoadedLogicalDuplicate(p.getServer(), data, logicalKey)) {
            return RecoverResult.fail("duplicate already loaded");
        }
        String typeId = recoverEntityTypeId(data);
        if (typeId.isBlank()) {
            return RecoverResult.fail("missing saved entity type");
        }

        ResourceLocation id = ResourceLocation.tryParse(typeId);
        if (id == null) {
            return RecoverResult.fail("invalid entity type '" + typeId + "'");
        }
        EntityType<?> entityType = ForgeRegistries.ENTITY_TYPES.getValue(id);
        if (entityType == null) {
            return RecoverResult.fail("unknown entity type '" + typeId + "'");
        }

        ServerLevel level = p.serverLevel();
        Entity spawned = entityType.create(level);
        if (!(spawned instanceof LivingEntity recovered)
                || (!(recovered instanceof TamableAnimal) && !(recovered instanceof ModifedToBeTameable))) {
            return RecoverResult.fail("stored type is not tamable");
        }

        CompoundTag snapshot = data.entitySnapshot == null ? new CompoundTag() : data.entitySnapshot.copy();
        if (!snapshot.isEmpty()) {
            recovered.load(snapshot);
        }

        recovered.setUUID(data.uuid);
        recovered.moveTo(p.getX(), p.getY(), p.getZ(), p.getYRot(), p.getXRot());
        recovered.setDeltaMovement(0.0D, 0.0D, 0.0D);
        UUID ownerId = p.getUUID();
        enforceRecoveredTameOwner(recovered, ownerId);

        if (!level.addFreshEntity(recovered)) {
            return RecoverResult.fail("spawn failed (UUID conflict or invalid state)");
        }
        clearAdminCloneTags(recovered);

        boolean normalized = LevelSystem.reapplyTypeBasePlusBonuses(recovered, data);
        if (!normalized) {
            LevelSystem.updateTameName(recovered, data);
            recovered.setHealth(recovered.getMaxHealth());
        }
        finalizeRecoveredLivingState(recovered, data);
        restoreRecoveredAppearance(recovered, snapshot);

        data.ownerUUID = p.getUUID();
        TameRegistry.bindEntityToData(recovered, data);
        data.lastKnownDimension = recovered.level().dimension().location().toString();
        data.lastKnownX = recovered.blockPosition().getX();
        data.lastKnownY = recovered.blockPosition().getY();
        data.lastKnownZ = recovered.blockPosition().getZ();
        data.lastKnownGameTime = recovered.level().getGameTime();
        CompoundTag refreshedSnapshot = new CompoundTag();
        recovered.save(refreshedSnapshot);
        data.entitySnapshot = refreshedSnapshot;
        TameRegistry.register(data);
        TameRegistry.markDirty();
        return RecoverResult.ok(recovered);
    }

    private static RecoverResult recoverPetEntityAtLocation(ServerPlayer owner, SpawnTarget target, TameData data) {
        if (com.github.alexthe668.domesticationinnovation.server.tameslevel.compat.BewereagerCompat.isLocked(data)) return RecoverResult.fail("hostile Bewereager cannot be controlled");
        if (target == null || target.level == null || target.pos == null || data == null) {
            return RecoverResult.fail("invalid context");
        }
        MinecraftServer server = target.level.getServer();
        UUID resolvedOwnerId = owner != null ? owner.getUUID() : data.ownerUUID;
        if (resolvedOwnerId == null) {
            return RecoverResult.fail("missing owner");
        }
        logRebuildTrace("recoverPetEntityAtLocation.begin", data,
                "owner=" + resolvedOwnerId + " targetDim=" + target.level.dimension().location() + " targetPos=" + target.pos);
        if (data.uuid == null) return RecoverResult.fail("missing tame UUID");
        clearGuardianAnchor(data);
        if (isDeadEntry(data.uuid)) {
            logRebuildTrace("recoverPetEntityAtLocation.fail", data, "tame is marked dead");
            return RecoverResult.fail("tame is marked dead");
        }
        String logicalKey = logicalTameKey(data);
        if (!logicalKey.isBlank() && hasLoadedLogicalDuplicate(server, data, logicalKey)) {
            logRebuildTrace("recoverPetEntityAtLocation.fail", data, "duplicate already loaded logicalKey=" + logicalKey);
            return RecoverResult.fail("duplicate already loaded");
        }
        String typeId = recoverEntityTypeId(data);
        if (typeId.isBlank()) {
            logRebuildTrace("recoverPetEntityAtLocation.fail", data, "missing saved entity type");
            return RecoverResult.fail("missing saved entity type");
        }

        ResourceLocation id = ResourceLocation.tryParse(typeId);
        if (id == null) {
            logRebuildTrace("recoverPetEntityAtLocation.fail", data, "invalid entity type " + typeId);
            return RecoverResult.fail("invalid entity type '" + typeId + "'");
        }
        EntityType<?> entityType = ForgeRegistries.ENTITY_TYPES.getValue(id);
        if (entityType == null) {
            logRebuildTrace("recoverPetEntityAtLocation.fail", data, "unknown entity type " + typeId);
            return RecoverResult.fail("unknown entity type '" + typeId + "'");
        }

        Entity spawned = entityType.create(target.level);
        if (!(spawned instanceof LivingEntity recovered)
                || (!(recovered instanceof TamableAnimal) && !(recovered instanceof ModifedToBeTameable))) {
            logRebuildTrace("recoverPetEntityAtLocation.fail", data, "stored type is not tamable");
            return RecoverResult.fail("stored type is not tamable");
        }

        CompoundTag snapshot = data.entitySnapshot == null ? new CompoundTag() : data.entitySnapshot.copy();
        if (!snapshot.isEmpty()) {
            recovered.load(snapshot);
        }

        recovered.setUUID(data.uuid);
        recovered.moveTo(target.pos.x, target.pos.y, target.pos.z, target.yRot, target.xRot);
        recovered.setDeltaMovement(0.0D, 0.0D, 0.0D);
        recovered.getPersistentData().putBoolean(ADMIN_CLONE_SILENT_TAG, true);
        enforceRecoveredTameOwner(recovered, resolvedOwnerId);

        if (!target.level.addFreshEntity(recovered)) {
            logRebuildTrace("recoverPetEntityAtLocation.fail", data, "spawn failed UUID conflict or invalid state");
            return RecoverResult.fail("spawn failed (UUID conflict or invalid state)");
        }
        clearAdminCloneTags(recovered);

        boolean normalized = LevelSystem.reapplyTypeBasePlusBonuses(recovered, data);
        if (!normalized) {
            LevelSystem.updateTameName(recovered, data);
            recovered.setHealth(recovered.getMaxHealth());
        }
        finalizeRecoveredLivingState(recovered, data);
        restoreRecoveredAppearance(recovered, snapshot);

        data.ownerUUID = resolvedOwnerId;
        data.stored = false;
        TameRegistry.bindEntityToData(recovered, data);
        data.lastKnownDimension = recovered.level().dimension().location().toString();
        data.lastKnownX = recovered.blockPosition().getX();
        data.lastKnownY = recovered.blockPosition().getY();
        data.lastKnownZ = recovered.blockPosition().getZ();
        data.lastKnownGameTime = recovered.level().getGameTime();
        CompoundTag refreshedSnapshot = new CompoundTag();
        recovered.save(refreshedSnapshot);
        data.entitySnapshot = refreshedSnapshot;
        TameRegistry.register(data);
        TameRegistry.markDirty();
        logRebuildTrace("recoverPetEntityAtLocation.success", data,
                "entityUuid=" + recovered.getUUID() + " entityTlId=" + TameData.getTlId(recovered) + " targetDim=" + target.level.dimension().location() + " targetPos=" + target.pos);
        return RecoverResult.ok(recovered);
    }

    private static int teleportAll(CommandSourceStack source) {
        ServerPlayer p = source.getPlayer();
        List<TameData> requested = ownedTamesForAllCommands(p.getUUID());
        List<LivingEntity> targets = new ArrayList<>();
        List<TameData> queuedTargets = new ArrayList<>();
        int queued = 0;
        int queueFailed = 0;
        List<String> failedQueueNames = new ArrayList<>();
        int cost = 0;
        int crossDimension = 0;
        int skippedDuel = 0;
        for (TameData d : requested) {
            if (d == null || d.dead) {
                continue;
            }
            if (isDuelLocked(d)) {
                skippedDuel++;
                continue;
            }
            LivingEntity ta = findLoadedOwnedLivingTameByIdentity(source, p.getUUID(), d);
            if (ta == null) {
                boolean cross = isCrossDimension(d, p);
                queuedTargets.add(d);
                cost += teleportCostFor(d, cross);
                if (cross) crossDimension++;
                continue;
            }
            boolean cross = isCrossDimension(ta, p);
            targets.add(ta);
            cost += teleportCostFor(d, cross);
            if (cross) crossDimension++;
        }
        TeleportPaymentResult payment = payTeleportXp(p, cost, targets.size() + queuedTargets.size());
        if (!payment.success) return error(p, payment.error);
        for (LivingEntity ta : targets) {
            TameData data = TameRegistry.get(ta.getUUID());
            if (data == null) data = TameRegistry.getByTlId(TameData.getTlId(ta));
            if (consumeHungerForCommandTeleport(p, data, ta)) {
                teleportLivingTameToPlayer(ta, p);
            }
        }
        for (TameData d : queuedTargets) {
            if (!consumeHungerForCommandTeleport(p, d, null)) {
                queueFailed++;
                failedQueueNames.add(tameDisplayName(d) + " (no food)");
                continue;
            }
            UnloadedTpResult unloaded = tpUnloadedViaLanternOrRecover(source, p, d);
            if (unloaded.success) {
                queued++;
            } else {
                queueFailed++;
                if (!d.horseType) failedQueueNames.add(tameDisplayName(d));
            }
        }
        sendTeleportNames(p, targets, queuedTargets);
        sendDuelCommandSkipNotice(p, skippedDuel, "tp");
        if (!failedQueueNames.isEmpty()) {
            p.sendSystemMessage(Component.literal("do /tames recover ... for: " + compactRecoverNames(failedQueueNames)).withStyle(ChatFormatting.RED));
        }
        return 1;
    }

