    private static int duelTeleportBatch(CommandSourceStack source, List<TameData> requested, String label) {
        ServerPlayer player = source.getPlayer();
        if (player == null) {
            return 0;
        }
        int moved = 0;
        int skippedNotInDuel = 0;
        int failed = 0;
        List<String> failedNames = new ArrayList<>();
        for (TameData data : requested) {
            if (data == null || data.dead) {
                continue;
            }
            if (!isDuelLocked(data)) {
                skippedNotInDuel++;
                continue;
            }
            TamableAnimal tame = findLoadedOwnedTameByUuid(source, player.getUUID(), data.uuid);
            if (tame == null || !tame.isAlive()) {
                failed++;
                failedNames.add(tameDisplayName(data) + " (not loaded/alive)");
                continue;
            }
            duelTeleportLoadedToPlayer(source, player, tame);
            moved++;
        }
        if (moved <= 0 && failed <= 0 && skippedNotInDuel > 0) {
            return error(player, "No selected tames are currently in a duel.");
        }
        player.sendSystemMessage(buildTeleportSummary(label, moved, 0, 0, failed, 0, 0));
        if (skippedNotInDuel > 0) {
            player.sendSystemMessage(Component.literal("Skipped " + skippedNotInDuel + " tames that are not in a duel.").withStyle(ChatFormatting.GRAY));
        }
        if (!failedNames.isEmpty()) {
            player.sendSystemMessage(Component.literal("DuelTP failures: " + String.join("; ", failedNames)).withStyle(ChatFormatting.RED));
        }
        return moved > 0 ? 1 : 0;
    }

    private static void duelTeleportLoadedToPlayer(CommandSourceStack source, ServerPlayer player, TamableAnimal tame) {
        if (player == null || tame == null || !tame.isAlive()) {
            return;
        }
        TameData data = TameRegistry.get(tame.getUUID());
        clearGuardianAnchor(data);
        TameTransferService.TransferResult result = TameTransferService.transferToPlayer(tame, player, data);
        if (!result.success()) {
            System.err.println("[TamesLevel] Duel teleport failed for tame " + tame.getUUID() + ": " + result.error());
            return;
        }
        TamableAnimal moved = result.entity();
        if (moved != null) {
            LivingEntity duelTarget = TameDuelManager.findNearestLoadedOpponent(source.getServer(), moved);
            if (duelTarget != null && duelTarget.isAlive()) {
                moved.setTarget(duelTarget);
            }
        }
    }

    private static TeleportPaymentResult payTeleportXp(ServerPlayer player, int cost, int teleportedTames) {
        if (player == null) {
            return TeleportPaymentResult.fail("player unavailable");
        }
        int normalizedCost = Math.max(0, cost);
        int normalizedTeleports = Math.max(0, teleportedTames);
        int availableCredits = TameRegistry.getTeleportApprovedCredits(player.getUUID());
        int missingTeleports = Math.max(0, normalizedTeleports - availableCredits);
        int approvedItemsNeeded = missingTeleports <= 0 ? 0 : (int) Math.ceil(missingTeleports / 10.0D);
        ItemStack paymentStack = player.getMainHandItem();
        int requiredPaymentPoints = approvedItemsNeeded * FOOD_POINTS_PER_APPROVED_ITEM;
        if (approvedItemsNeeded > 0 && approvedOrFoodPaymentPoints(paymentStack) < requiredPaymentPoints) {
            ItemStack offhand = player.getOffhandItem();
            if (approvedOrFoodPaymentPoints(offhand) >= requiredPaymentPoints) {
                paymentStack = offhand;
            }
        }
        if (normalizedTeleports > 0 && (availableCredits > 0 || approvedItemsNeeded > 0)) {
            if (approvedItemsNeeded == 0 || approvedOrFoodPaymentPoints(paymentStack) >= requiredPaymentPoints) {
                if (approvedItemsNeeded > 0) {
                    consumeApprovedOrFoodPaymentPoints(paymentStack, requiredPaymentPoints);
                }
                int remainingCredits = Math.max(0, availableCredits + approvedItemsNeeded * 10 - normalizedTeleports);
                TameRegistry.setTeleportApprovedCredits(player.getUUID(), remainingCredits);
                String itemLabel = approvedItemsNeeded <= 0
                        ? "used stored approved TP credits"
                        : "spent " + formatApprovedItemRequirement(approvedItemsNeeded);
                player.sendSystemMessage(Component.literal("Teleport payment: " + itemLabel + " (" + remainingCredits + " TP credit" + (remainingCredits == 1 ? "" : "s") + " left).").withStyle(ChatFormatting.WHITE));
                return TeleportPaymentResult.ok(0);
            }
        }
        if (normalizedCost <= 0) {
            return TeleportPaymentResult.ok(0);
        }
        int currentXp = currentXpPoints(player);
        if (currentXp < normalizedCost) {
            String requirement = approvedItemsNeeded > 0
                    ? normalizedCost + " XP or " + formatApprovedItemRequirement(approvedItemsNeeded)
                    : normalizedCost + " XP";
            return TeleportPaymentResult.fail("Not enough payment. Need " + requirement + " (you have " + currentXp + " XP and " + availableCredits + " TP credits).");
        }
        player.giveExperiencePoints(-normalizedCost);
        return TeleportPaymentResult.ok(normalizedCost);
    }

    private static int teleportCostFor(TameData data, boolean crossDimension) {
        int base = Math.max(1, data == null ? 1 : data.level);
        return crossDimension ? (base * 2) : base;
    }

    private static int teleportGuardianCostFor(TameData data, boolean crossDimension) {
        int normal = teleportCostFor(data, crossDimension);
        return Math.max(1, (int) Math.ceil(normal / 4.0D));
    }

    private static String validateGuardianTeleport(CommandSourceStack source, ServerPlayer owner, TameData data) {
        if (source == null || owner == null || data == null) {
            return "invalid context";
        }
        if (!data.hasHome) {
            return "no current guardian location";
        }
        String validationError = validateUnloadedHomeTeleport(
                source,
                owner,
                data,
                new SpawnTarget(owner.serverLevel(), owner.position(), owner.getYRot(), owner.getXRot())
        );
        if (validationError != null && (data.entitySnapshot == null || data.entitySnapshot.isEmpty())) {
            return validationError;
        }
        return null;
    }

    private static boolean isCrossDimension(TamableAnimal tame, ServerPlayer player) {
        return tame != null && player != null && !tame.level().dimension().equals(player.level().dimension());
    }

    private static boolean isCrossDimension(LivingEntity tame, ServerPlayer player) {
        return tame != null && player != null && !tame.level().dimension().equals(player.level().dimension());
    }

    private static boolean isCrossDimension(TameData data, ServerPlayer player) {
        if (data == null || player == null || data.lastKnownDimension == null || data.lastKnownDimension.isBlank()) {
            return false;
        }
        ResourceLocation lastKnown = ResourceLocation.tryParse(data.lastKnownDimension);
        return lastKnown != null && !player.level().dimension().location().equals(lastKnown);
    }

    private static boolean isCrossDimension(TameData data, ServerLevel level) {
        if (data == null || level == null || data.lastKnownDimension == null || data.lastKnownDimension.isBlank()) {
            return false;
        }
        ResourceLocation lastKnown = ResourceLocation.tryParse(data.lastKnownDimension);
        return lastKnown != null && !level.dimension().location().equals(lastKnown);
    }

    private static String validateUnloadedTeleportForPlayer(CommandSourceStack source, ServerPlayer owner, TameData data) {
        if (source == null || owner == null || data == null) {
            return "invalid context";
        }
        SpawnTarget target = new SpawnTarget(owner.serverLevel(), owner.position(), owner.getYRot(), owner.getXRot());
        String validationError = validateUnloadedHomeTeleport(source, owner, data, target);
        if (validationError != null && (data.entitySnapshot == null || data.entitySnapshot.isEmpty())) {
            return validationError;
        }
        return null;
    }

    private static int recoverCostFor(TameData data) {
        if (data == null) return 0;
        int invested = Math.max(0, LevelSystem.estimateInvestedXp(data));
        if (invested <= 0) return 0;
        return Math.max(1, (int) Math.ceil(invested / 4.0D));
    }

    private static String recoverEntityTypeId(TameData data) {
        if (data != null && data.entitySnapshot != null && data.entitySnapshot.contains("id")) {
            String fromSnapshot = data.entitySnapshot.getString("id");
            if (fromSnapshot != null && !fromSnapshot.isBlank()) {
                return fromSnapshot.trim().toLowerCase(Locale.ROOT);
            }
        }

        String raw = data == null ? "" : data.type;
        if (raw == null || raw.isBlank()) return "";

        String normalized = raw.trim();
        if (normalized.startsWith("entity.")) {
            normalized = normalized.substring("entity.".length());
            int firstDot = normalized.indexOf('.');
            if (firstDot > 0 && !normalized.contains(":")) {
                normalized = normalized.substring(0, firstDot) + ":" + normalized.substring(firstDot + 1);
            }
        }
        if (!normalized.contains(":")) {
            normalized = "minecraft:" + normalized;
        }
        return normalized.toLowerCase(Locale.ROOT);
    }

    private static void teleportTameToPlayer(TamableAnimal tame, ServerPlayer player) {
        if (tame == null || player == null) return;
        TameData data = TameRegistry.get(tame.getUUID());
        clearGuardianAnchor(data);
        TameTransferService.TransferResult result = TameTransferService.transferToPlayer(tame, player, data);
        if (!result.success()) {
            System.err.println("[TamesLevel] Command teleport failed for tame " + tame.getUUID() + ": " + result.error());
            return;
        }
        TamableAnimal moved = result.entity();
        if (moved != null) {
            applyMovementOverride(moved, MovementOrder.FOLLOW);
            queueDelayedTeleportClientRefresh(player, moved);
        }
    }

