    private static void teleportTameToLocation(TamableAnimal tame, SpawnTarget target, boolean exactTarget) {
        if (tame == null || target == null || target.level == null || target.pos == null) return;
        SpawnTarget resolvedTarget = exactTarget ? target : findSafeTameTeleportTarget(tame, target);
        if (resolvedTarget == null) {
            resolvedTarget = target;
        }
        TameData data = TameRegistry.get(tame.getUUID());
        clearGuardianAnchor(data);
        TameTransferService.TransferResult result = TameTransferService.transferToLocation(
                tame,
                resolvedTarget.level,
                resolvedTarget.pos.x,
                resolvedTarget.pos.y,
                resolvedTarget.pos.z,
                resolvedTarget.yRot,
                resolvedTarget.xRot,
                data,
                exactTarget
        );
        if (!result.success()) {
            System.err.println("[TamesLevel] Command tphome failed for tame " + tame.getUUID() + ": " + result.error());
            return;
        }
        TamableAnimal moved = result.entity();
        if (moved != null) {
            ServerPlayer owner = ownerPlayerForRefresh(tame, moved, data);
            queueDelayedTeleportClientRefresh(owner, moved);
        }
    }

    private static void teleportLivingTameToLocation(LivingEntity tame, SpawnTarget target, boolean exactTarget) {
        if (tame instanceof TamableAnimal tamable) {
            teleportTameToLocation(tamable, target, exactTarget);
            return;
        }
        if (tame == null || target == null || target.level == null || target.pos == null || !tame.isAlive()) return;
        TameData data = TameRegistry.get(tame.getUUID());
        clearGuardianAnchor(data);
        TameTransferService.transferInterfaceToLocation(tame, target.level, target.pos.x, target.pos.y, target.pos.z,
                target.yRot, target.xRot, data, exactTarget);
    }

    private static SpawnTarget findSafeTameTeleportTarget(TamableAnimal tame, SpawnTarget target) {
        if (tame == null || target == null || target.level == null || target.pos == null) {
            return target;
        }
        AABB exactBox = tame.getDimensions(tame.getPose()).makeBoundingBox(target.pos.x, target.pos.y, target.pos.z);
        if (target.level.noCollision(tame, exactBox)
                && target.level.getEntities(tame, exactBox.inflate(0.05D), entity -> entity instanceof LivingEntity && entity.isAlive()).isEmpty()) {
            return target;
        }
        int baseX = Mth.floor(target.pos.x);
        int baseY = Mth.floor(target.pos.y);
        int baseZ = Mth.floor(target.pos.z);
        int hash = Math.floorMod(tame.getUUID().hashCode(), 25);
        List<BlockPos> candidates = new ArrayList<>(25);
        for (int radius = 0; radius <= 2; radius++) {
            for (int dx = -radius; dx <= radius; dx++) {
                for (int dz = -radius; dz <= radius; dz++) {
                    if (Math.max(Math.abs(dx), Math.abs(dz)) != radius) {
                        continue;
                    }
                    candidates.add(new BlockPos(baseX + dx, baseY, baseZ + dz));
                }
            }
        }
        if (!candidates.isEmpty()) {
            java.util.Collections.rotate(candidates, hash);
        }
        for (BlockPos candidate : candidates) {
            SpawnTarget safe = safeTeleportTargetAt(tame, target, candidate);
            if (safe != null) {
                return safe;
            }
        }
        return target;
    }

    private static SpawnTarget safeTeleportTargetAt(TamableAnimal tame, SpawnTarget original, BlockPos candidateBase) {
        if (tame == null || original == null || original.level == null || candidateBase == null) {
            return null;
        }
        ServerLevel level = original.level;
        for (int dy = -1; dy <= 1; dy++) {
            BlockPos feet = candidateBase.offset(0, dy, 0);
            BlockPos head = feet.above();
            if (!level.getBlockState(feet).canBeReplaced() || !level.getBlockState(head).canBeReplaced()) {
                continue;
            }
            Vec3 pos = new Vec3(feet.getX() + 0.5D, feet.getY(), feet.getZ() + 0.5D);
            AABB box = tame.getDimensions(tame.getPose()).makeBoundingBox(pos.x, pos.y, pos.z);
            if (!level.noCollision(tame, box)) {
                continue;
            }
            if (!level.getEntities(tame, box.inflate(0.05D), entity -> entity instanceof LivingEntity && entity.isAlive()).isEmpty()) {
                continue;
            }
            return new SpawnTarget(level, pos, original.yRot, original.xRot);
        }
        return null;
    }

    public static boolean autoFollowTeleportUnloadedToOwner(ServerPlayer owner, TameData data) {
        if (owner == null || data == null || data.uuid == null || data.dead) {
            return false;
        }
        if (data.lastKnownDimension != null && !data.lastKnownDimension.isBlank()) {
            ResourceLocation lastKnown = ResourceLocation.tryParse(data.lastKnownDimension);
            if (lastKnown != null && !owner.serverLevel().dimension().location().equals(lastKnown)) {
                return false;
            }
        }
        SpawnTarget target = new SpawnTarget(owner.serverLevel(), owner.position(), owner.getYRot(), owner.getXRot());
        UnloadedTpResult result = tryImmediateChunkLoadTeleportSilent(owner.createCommandSourceStack(), owner, data, target);
        return result.success;
    }

    public static boolean autoFollowTeleportUnloadedToLocation(ServerPlayer owner, TameData data, ServerLevel level, Vec3 pos, float yRot, float xRot) {
        if (owner == null || data == null || data.uuid == null || data.dead || level == null || pos == null) {
            return false;
        }
        SpawnTarget target = new SpawnTarget(level, pos, yRot, xRot);
        boolean crossDimension = isCrossDimension(data, level);
        if (!crossDimension && data.lastKnownDimension != null && !data.lastKnownDimension.isBlank()) {
            ResourceLocation lastKnown = ResourceLocation.tryParse(data.lastKnownDimension);
            if (lastKnown != null && !level.dimension().location().equals(lastKnown)) {
                return false;
            }
        }
        UnloadedTpResult result = tryImmediateChunkLoadTeleportSilent(owner.createCommandSourceStack(), owner, data, target, crossDimension);
        return result.success;
    }

    public static boolean autoFollowTeleportViaTpPath(ServerPlayer owner, TameData data, ServerLevel level, Vec3 pos, float yRot, float xRot) {
        if (owner == null || data == null || data.uuid == null || data.dead || level == null || pos == null) {
            return false;
        }
        if (TameDuelManager.isTameInDuel(data.uuid)) {
            return false;
        }
        if (!canAttemptAutoFollowUnloadedTeleport(owner.getServer(), data)) {
            return false;
        }
        SpawnTarget target = new SpawnTarget(level, pos, yRot, xRot);
        TamableAnimal loaded = owner.getServer() == null ? null : findLoadedTameByIdentity(owner.getServer(), data.uuid, data.tlId);
        if (loaded != null && loaded.isAlive()) {
                teleportTameToLocation(loaded, target, isAssignedBedTarget(data, target));
            TamableAnimal moved = owner.getServer() == null ? null : findLoadedTameByIdentity(owner.getServer(), data.uuid, data.tlId);
            if (moved != null) {
                applyMovementOverride(moved, MovementOrder.FOLLOW);
                resendEntityToRelevantPlayers(moved);
            }
            clearAutoFollowRetryState(data);
            return true;
        }
        boolean crossDimension = isCrossDimension(data, target.level);
        String validationError = validateUnloadedHomeTeleport(owner.createCommandSourceStack(), owner, data, target);
        if (validationError != null) {
            return false;
        }
        UnloadedTpResult result = queueAutoFollowImmediateChunkTeleport(owner.createCommandSourceStack(), owner, data, target, crossDimension);
        if (result.success) {
            TamableAnimal moved = owner.getServer() == null ? null : findLoadedTameByIdentity(owner.getServer(), data.uuid, data.tlId);
            if (moved != null) {
                applyMovementOverride(moved, MovementOrder.FOLLOW);
                resendEntityToRelevantPlayers(moved);
            }
        }
        return result.success;
    }

