    public static void queueTrackingClientReload(ServerPlayer player, LivingEntity tame) {
        if (player == null || tame == null || tame.level().isClientSide
                || !TameEntityAdapter.isTame(tame) || !tame.isAlive() || tame.level().getServer() == null) {
            return;
        }
        MinecraftServer server = tame.level().getServer();
        long now = server.overworld() == null ? 0L : server.overworld().getGameTime();
        TrackingClientRefreshKey key = new TrackingClientRefreshKey(player.getUUID(), tame.getUUID());
        ACTIVE_CLIENT_TRACKERS.add(key);
        PENDING_TRACKING_CLIENT_REFRESH.put(key, new PendingTrackingClientRefresh(
                player.getUUID(), tame.getUUID(), TameData.getTlId(tame),
                tame.level().dimension().location().toString(),
                now + TRACKING_CLIENT_REFRESH_DELAY_TICKS
        ));
    }

    public static void cancelTrackingClientReload(ServerPlayer player, Entity entity) {
        if (player == null || entity == null) {
            return;
        }
        TrackingClientRefreshKey key = new TrackingClientRefreshKey(player.getUUID(), entity.getUUID());
        ACTIVE_CLIENT_TRACKERS.remove(key);
        PENDING_TRACKING_CLIENT_REFRESH.remove(key);
    }

    private static boolean processPendingTrackingClientRefresh(MinecraftServer server,
                                                               PendingTrackingClientRefresh pending) {
        if (server == null || pending == null) {
            return true;
        }
        long now = server.overworld() == null ? 0L : server.overworld().getGameTime();
        if (pending.dueTick() > now) {
            return false;
        }
        ServerPlayer player = server.getPlayerList().getPlayer(pending.playerUuid());
        LivingEntity tame = findLoadedLivingTameByIdentity(server, pending.tameUuid(), pending.tlId());
        if (player == null || player.connection == null || player.isRemoved()
                || tame == null || !tame.isAlive()
                || player.level() != tame.level()
                || player.distanceToSqr(tame) > 192.0D * 192.0D
                || !tame.level().dimension().location().toString().equals(pending.dimensionId())) {
            return true;
        }
        sendFullEntityRefresh(player, tame);
        return true;
    }

    private static boolean processPendingTeleportClientRefresh(MinecraftServer server, UUID key, PendingTeleportClientRefresh pending) {
        if (server == null || pending == null) {
            return true;
        }
        long now = server.overworld() == null ? 0L : server.overworld().getGameTime();
        if (pending.dueTick() > now) {
            return false;
        }
        LivingEntity moved = findLoadedLivingTameByIdentity(server, pending.tameUuid(), pending.tlId());
        if (moved == null || !moved.isAlive()) {
            return true;
        }
        if (!moved.level().dimension().location().toString().equals(pending.dimensionId())) {
            return true;
        }
        resendEntityToRelevantPlayers(moved, pending.strongRefresh());
        return true;
    }

    private static ServerPlayer ownerPlayerForRefresh(TamableAnimal original, TamableAnimal moved, TameData data) {
        MinecraftServer server = moved == null || moved.level() == null ? null : moved.level().getServer();
        if (server == null && original != null && original.level() != null) {
            server = original.level().getServer();
        }
        if (server == null) {
            return null;
        }
        UUID ownerId = null;
        if (data != null && data.ownerUUID != null) {
            ownerId = data.ownerUUID;
        } else if (moved != null && moved.getOwnerUUID() != null) {
            ownerId = moved.getOwnerUUID();
        } else if (original != null) {
            ownerId = original.getOwnerUUID();
        }
        return ownerId == null ? null : server.getPlayerList().getPlayer(ownerId);
    }

    private static void resendEntityToRelevantPlayers(LivingEntity tame) {
        resendEntityToRelevantPlayers(tame, false);
    }

    private static void resendEntityToRelevantPlayers(LivingEntity tame, boolean strongRefresh) {
        if (tame == null || !(tame.level() instanceof ServerLevel level)) {
            return;
        }
        // Keep the historical invisibility repair, but only for players already tracked by
        // vanilla or close enough that the tracker should have picked them up after the move.
        // This includes newly-nearby viewers if tracking failed, without returning to a
        // dimension-wide resend.
        if (strongRefresh) {
            for (ServerPlayer viewer : level.players()) {
                if (viewer == null || viewer.connection == null || viewer.isRemoved()
                        || viewer.distanceToSqr(tame) > 192.0D * 192.0D) continue;
                sendFullEntityRefresh(viewer, tame);
            }
            return;
        }
        level.getChunkSource().broadcastAndSend(tame, new ClientboundTeleportEntityPacket(tame));
    }

    public static void clearClientTracking(ServerPlayer player) {
        ACTIVE_CLIENT_TRACKERS.removeIf(key -> key.playerUuid().equals(player.getUUID()));
        PENDING_TRACKING_CLIENT_REFRESH.keySet().removeIf(key -> key.playerUuid().equals(player.getUUID()));
    }

    private static void sendFullEntityRefresh(ServerPlayer viewer, LivingEntity tame) {
        // Never spawn a client copy outside vanilla tracking: it would miss updates and removal.
        if (viewer.level() != tame.level() || !ACTIVE_CLIENT_TRACKERS.contains(
                new TrackingClientRefreshKey(viewer.getUUID(), tame.getUUID()))) return;
        List<net.minecraft.network.syncher.SynchedEntityData.DataValue<?>> values = tame.getEntityData().getNonDefaultValues();
        sendClientPacket(viewer, new ClientboundRemoveEntitiesPacket(tame.getId()));
        sendClientPacket(viewer, tame.getAddEntityPacket());
        if (values != null && !values.isEmpty()) {
            sendClientPacket(viewer, new ClientboundSetEntityDataPacket(tame.getId(), values));
        }
        sendClientPacket(viewer, new ClientboundUpdateAttributesPacket(
                tame.getId(), tame.getAttributes().getSyncableAttributes()));
        sendClientPacket(viewer, createEquipmentPacket(tame));
        sendClientPacket(viewer, new ClientboundTeleportEntityPacket(tame));
        com.github.alexthe668.domesticationinnovation.server.entity.TameTagSync.sendCurrent(viewer, tame);
    }

    private static ClientboundSetEquipmentPacket createEquipmentPacket(LivingEntity tame) {
        List<Pair<EquipmentSlot, ItemStack>> equipment = new ArrayList<>();
        for (EquipmentSlot slot : EquipmentSlot.values()) {
            equipment.add(Pair.of(slot, tame.getItemBySlot(slot).copy()));
        }
        return new ClientboundSetEquipmentPacket(tame.getId(), equipment);
    }

    private static void sendClientPacket(ServerPlayer player, Packet<?> packet) {
        if (player == null || packet == null || player.connection == null) {
            return;
        }
        player.connection.send(packet);
    }

    public static boolean hasPendingImmediateChunkTeleport(TameData data) {
        if (data == null) {
            return false;
        }
        UUID key = data.tlId != null ? data.tlId : data.uuid;
        return key != null && PENDING_IMMEDIATE_CHUNK_TELEPORTS.containsKey(key);
    }

    public static boolean canAttemptAutoFollowUnloadedTeleport(MinecraftServer server, TameData data) {
        if (data == null) {
            return false;
        }
        UUID key = autoFollowKey(data);
        if (key == null) {
            return false;
        }
        if (AUTO_FOLLOW_RECOVER_REQUIRED.contains(key)) {
            return false;
        }
        if (server == null || server.overworld() == null) {
            return !AUTO_FOLLOW_RETRY_AFTER.containsKey(key);
        }
        Long retryAt = AUTO_FOLLOW_RETRY_AFTER.get(key);
        return retryAt == null || server.overworld().getGameTime() >= retryAt;
    }

