    private static int leaderboard(CommandSourceStack source, String mode, boolean includeAll, String groupFilter, String typeFilter, int requestedLimit) {
        return leaderboard(source, mode, includeAll, groupFilter, typeFilter, requestedLimit, false);
    }

    private static int leaderboardOrdered(CommandSourceStack source, String sortType, String order,
                                          boolean includeAll, String groupFilter, String typeFilter) {
        boolean ascending = order != null && order.equalsIgnoreCase("asc");
        if (!ascending && (order == null || !order.equalsIgnoreCase("desc"))) {
            return error(source.getPlayer(), "Sort direction must be asc or desc.");
        }
        return leaderboard(source, sortType, includeAll, groupFilter, typeFilter, 10, ascending);
    }

    private static int leaderboard(CommandSourceStack source, String mode, boolean includeAll, String groupFilter, String typeFilter, int requestedLimit, boolean ascending) {
        ServerPlayer p = source.getPlayer();
        String m = mode == null ? "mix" : mode.trim().toLowerCase(Locale.ROOT);
        if (m.equals("daysalive")) m = "days";
        if (m.equals("level")) m = "lvl";
        if (!Set.of("mix", "score", "kills", "deaths", "assists", "days", "lvl", "mmr").contains(m)) {
            return error(p, "Invalid sort order. Use daysAlive, deaths, kills, assists, level, or mmr.");
        }
        List<TameData> entries = new ArrayList<>();
        for (TameData d : TameRegistry.TAMES.values()) {
            if (!includeAll && !p.getUUID().equals(d.ownerUUID)) continue;
            if (groupFilter != null && !isInGroup(d, groupFilter)) continue;
            if (typeFilter != null && !matchesTypeFilter(d, typeFilter)) continue;
            if (leaderboardInvestedXp(d) <= 0) continue;
            entries.add(d);
        }
        Comparator<TameData> comparator;
        if (m.equals("mix") || m.equals("score")) comparator = Comparator.comparingInt(TameCommands::weightedCombatScore);
        else if (m.equals("kills")) comparator = Comparator.comparingInt(data -> data.kills);
        else if (m.equals("deaths")) comparator = Comparator.comparingInt(data -> data.deaths);
        else if (m.equals("assists")) comparator = Comparator.comparingInt(data -> data.assists);
        else if (m.equals("days")) comparator = Comparator.comparingLong(data -> daysAlive(source, data));
        else if (m.equals("mmr")) comparator = Comparator.comparingInt(data -> data.duelMmr);
        else comparator = Comparator.comparingInt(data -> data.level);
        if (!ascending) comparator = comparator.reversed();
        entries.sort(comparator.thenComparing(data -> data.name == null ? "" : data.name, String.CASE_INSENSITIVE_ORDER));

        if (entries.isEmpty()) return error(p, "No entries found.");
        int limit = Math.min(Math.max(1, requestedLimit), entries.size());
        String scope = includeAll ? "all players" : "your tames";
        String groupText = (groupFilter == null || groupFilter.isBlank()) ? "" : (" | group: " + groupFilter);
        String typeText = (typeFilter == null || typeFilter.isBlank()) ? "" : (" | type: " + normalizeTypeFilter(typeFilter));
        p.sendSystemMessage(Component.literal("---- Leaderboard (" + m + " " + (ascending ? "asc" : "desc") + ") | " + scope + groupText + typeText + " | showing " + limit + "/" + entries.size() + " ----").withStyle(ChatFormatting.GOLD));
        p.sendSystemMessage(Component.literal("score / kills / assists / deaths / days").withStyle(ChatFormatting.DARK_GRAY));
        String activeRankBucket = null;
        for (int i = 0; i < limit; i++) {
            TameData d = entries.get(i);
            DuelLeaderboardRankBucket rankBucket = duelLeaderboardRankBucket(d.duelMmr);
            if (m.equals("mmr") && !rankBucket.label().equals(activeRankBucket)) {
                activeRankBucket = rankBucket.label();
                p.sendSystemMessage(Component.literal("---" + activeRankBucket + ":---").withStyle(rankBucket.color()));
            }
            int score = weightedCombatScore(d);
            p.sendSystemMessage(Component.literal((i + 1) + ". ").withStyle(ChatFormatting.GOLD)
                    .append(m.equals("mmr") ? Component.literal("(" + d.duelMmr + ") ").withStyle(rankBucket.color()) : Component.empty())
                    .append(Component.literal("(" + ownerInitials(source.getServer(), d.ownerUUID) + ") ").withStyle(ChatFormatting.GRAY))
                    .append(Component.literal("[" + d.level + "] ").withStyle(ChatFormatting.YELLOW))
                    .append(Component.literal(d.name + " ").withStyle(ChatFormatting.AQUA))
                    .append(Component.literal("(" + shortEntityTypeName(d.type) + ")").withStyle(ChatFormatting.DARK_GRAY)));
            p.sendSystemMessage(Component.literal("   ").withStyle(ChatFormatting.DARK_GRAY)
                    .append(Component.literal("(").withStyle(ChatFormatting.DARK_GRAY))
                    .append(Component.literal(String.valueOf(score)).withStyle(ChatFormatting.LIGHT_PURPLE))
                    .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                    .append(Component.literal(String.valueOf(d.kills)).withStyle(ChatFormatting.RED))
                    .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                    .append(Component.literal(String.valueOf(d.assists)).withStyle(ChatFormatting.GREEN))
                    .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                    .append(Component.literal(String.valueOf(d.deaths)).withStyle(ChatFormatting.GRAY))
                    .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                    .append(Component.literal(String.valueOf(daysAlive(source, d))).withStyle(ChatFormatting.DARK_AQUA))
                    .append(Component.literal(")").withStyle(ChatFormatting.DARK_GRAY)));
        }
        return 1;
    }

    private static int duelLeaderboardSimple(CommandSourceStack source, boolean includeAll, boolean longForm) {
        return duelLeaderboard(source, "mmr", includeAll, null, null, 10, longForm);
    }

    private static int duelLeaderboard(CommandSourceStack source, String mode, boolean includeAll, String groupFilter, String typeFilter, int requestedLimit) {
        return duelLeaderboard(source, mode, includeAll, groupFilter, typeFilter, requestedLimit, true);
    }

    private static int duelLeaderboard(CommandSourceStack source, String mode, boolean includeAll, String groupFilter, String typeFilter, int requestedLimit, boolean longForm) {
        return duelLeaderboard(source, mode, includeAll, groupFilter, typeFilter, requestedLimit, longForm,
                null, "Duel Leaderboard", true);
    }

    private static int duelLeaderboard(CommandSourceStack source, String mode, boolean includeAll, String groupFilter,
                                       String typeFilter, int requestedLimit, boolean longForm,
                                       Set<UUID> participantFilter, String title, boolean includePlayers) {
        ServerPlayer p = source.getPlayer();
        String m = mode == null ? "mmr" : mode.trim().toLowerCase(Locale.ROOT);
        List<DuelLeaderboardEntry> entries = new ArrayList<>();
        for (TameData data : TameRegistry.TAMES.values()) {
            if (data == null || !hasRecordedDuelStats(data)) continue;
            if (participantFilter != null
                    && !participantFilter.contains(data.uuid)
                    && (data.tlId == null || !participantFilter.contains(data.tlId))) continue;
            if (!includeAll && !p.getUUID().equals(data.ownerUUID)) continue;
            if (groupFilter != null && !isInGroup(data, groupFilter)) continue;
            if (typeFilter != null && !matchesTypeFilter(data, typeFilter)) continue;
            entries.add(new DuelLeaderboardEntry(
                    data.uuid,
                    data.ownerUUID,
                    data.name,
                    data.type,
                    data.group,
                    data.level,
                    false,
                    data.duelMmr,
                    Math.max(0, data.duelWins),
                    Math.max(0, data.duelLosses),
                    Math.max(0, data.duelCount),
                    Math.max(0, data.duelKills),
                    Math.max(0, data.duelAssists),
                    Math.max(0, data.duelDeaths),
                    Math.max(0.0D, data.duelPoints)
            ));
        }
        if (includePlayers) for (Map.Entry<UUID, PlayerDuelStats> entry : TameRegistry.getPlayerDuelStats().entrySet()) {
            UUID playerId = entry.getKey();
            PlayerDuelStats stats = entry.getValue();
            if (playerId == null || stats == null || !hasRecordedDuelStats(stats)) continue;
            if (!includeAll && !p.getUUID().equals(playerId)) continue;
            if (groupFilter != null || typeFilter != null) continue;
            entries.add(new DuelLeaderboardEntry(
                    playerId,
                    playerId,
                    resolveDuelPlayerName(source.getServer(), playerId, stats),
                    "minecraft:player",
                    "",
                    0,
                    true,
                    stats.duelMmr,
                    Math.max(0, stats.duelWins),
                    Math.max(0, stats.duelLosses),
                    Math.max(0, stats.duelCount),
                    Math.max(0, stats.duelKills),
                    Math.max(0, stats.duelAssists),
                    Math.max(0, stats.duelDeaths),
                    Math.max(0.0D, stats.duelPoints)
            ));
        }

        sortDuelLeaderboardEntries(entries, m);
        if (entries.isEmpty()) return error(p, "No duel leaderboard entries found.");
        int limit = Math.min(Math.max(1, requestedLimit), entries.size());
        String scope = includeAll ? (includePlayers ? "all players" : "all participating tames") : "owned";
        String groupText = (groupFilter == null || groupFilter.isBlank()) ? "" : (" | group: " + groupFilter);
        String typeText = (typeFilter == null || typeFilter.isBlank()) ? "" : (" | type: " + normalizeTypeFilter(typeFilter));
        p.sendSystemMessage(Component.literal("---- " + title + " | " + scope + " | " + (longForm ? "long" : "short") + groupText + typeText + " | showing " + limit + "/" + entries.size() + " ----").withStyle(ChatFormatting.GOLD));
        if (longForm) {
            p.sendSystemMessage(Component.literal("wins / losses / duels / kills / assists / deaths / points").withStyle(ChatFormatting.DARK_GRAY));
        }
        String activeRankBucket = null;
        for (int i = 0; i < limit; i++) {
            DuelLeaderboardEntry entry = entries.get(i);
            if (m.equals("mmr") || "mmr".equals(m)) {
                DuelLeaderboardRankBucket rankBucket = duelLeaderboardRankBucket(entry.mmr());
                if (!rankBucket.label().equals(activeRankBucket)) {
                    activeRankBucket = rankBucket.label();
                    p.sendSystemMessage(Component.literal("---" + activeRankBucket + ":---").withStyle(rankBucket.color()));
                }
            }
            DuelLeaderboardRankBucket rankBucket = duelLeaderboardRankBucket(entry.mmr());
            MutableComponent line = Component.literal((i + 1) + ". ").withStyle(ChatFormatting.GOLD)
                    .append(Component.literal("(" + entry.mmr() + ") ").withStyle(rankBucket.color()))
                    .append(Component.literal("(" + ownerInitials(source.getServer(), entry.ownerUuid()) + ") ").withStyle(ChatFormatting.GRAY))
                    .append(Component.literal(entry.name() + " ").withStyle(ChatFormatting.AQUA))
                    .append(Component.literal("(" + shortEntityTypeName(entry.type()) + ")").withStyle(ChatFormatting.DARK_GRAY));
            p.sendSystemMessage(line);
            if (longForm) {
                line = Component.literal("   ").withStyle(ChatFormatting.DARK_GRAY)
                        .append(Component.literal("(").withStyle(ChatFormatting.DARK_GRAY))
                        .append(Component.literal(String.valueOf(entry.wins())).withStyle(ChatFormatting.GREEN))
                        .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                        .append(Component.literal(String.valueOf(entry.losses())).withStyle(ChatFormatting.RED))
                        .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                        .append(Component.literal(String.valueOf(entry.duelCount())).withStyle(ChatFormatting.DARK_AQUA))
                        .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                        .append(Component.literal(String.valueOf(entry.kills())).withStyle(ChatFormatting.RED))
                        .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                        .append(Component.literal(String.valueOf(entry.assists())).withStyle(ChatFormatting.GREEN))
                        .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                        .append(Component.literal(String.valueOf(entry.deaths())).withStyle(ChatFormatting.GRAY))
                        .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                        .append(Component.literal(formatDuelLeaderboardPoints(entry.totalPoints())).withStyle(ChatFormatting.LIGHT_PURPLE))
                        .append(Component.literal(")").withStyle(ChatFormatting.DARK_GRAY));
                p.sendSystemMessage(line);
            }
        }
        if (entries.size() > limit) {
            p.sendSystemMessage(Component.literal("... and " + (entries.size() - limit) + " more.").withStyle(ChatFormatting.DARK_GRAY));
        }
        return 1;
    }

