    private static DuelLeaderboardRankBucket duelLeaderboardRankBucket(int mmr) {
        if (mmr < 0) {
            if (mmr <= -1200) {
                return DUEL_RANK_NEG_POPEL;
            }
            if (mmr <= -900) {
                return DUEL_RANK_NEG_LAUCH;
            }
            if (mmr <= -600) {
                return DUEL_RANK_NEG_ZERO_AURA;
            }
            if (mmr <= -300) {
                return DUEL_RANK_NEG_OPFER;
            }
            return DUEL_RANK_NEG_LOSER;
        }
        int safeMmr = mmr;
        for (DuelLeaderboardRankBucket bucket : DUEL_LEADERBOARD_RANKS) {
            if (safeMmr >= bucket.minMmr()) {
                return bucket;
            }
        }
        return DUEL_LEADERBOARD_RANKS.get(DUEL_LEADERBOARD_RANKS.size() - 1);
    }

    private static void sortDuelLeaderboardEntries(List<DuelLeaderboardEntry> entries, String mode) {
        if (entries == null || entries.isEmpty()) {
            return;
        }
        String normalized = mode == null ? "mmr" : mode.trim().toLowerCase(Locale.ROOT);
        Comparator<DuelLeaderboardEntry> comparator;
        if (normalized.equals("kills")) comparator = Comparator.comparingInt(DuelLeaderboardEntry::kills).reversed();
        else if (normalized.equals("deaths")) comparator = Comparator.comparingInt(DuelLeaderboardEntry::deaths).reversed();
        else if (normalized.equals("assists")) comparator = Comparator.comparingInt(DuelLeaderboardEntry::assists).reversed();
        else if (normalized.equals("wins")) comparator = Comparator.comparingInt(DuelLeaderboardEntry::wins).reversed();
        else if (normalized.equals("losses")) comparator = Comparator.comparingInt(DuelLeaderboardEntry::losses).reversed();
        else if (normalized.equals("duels") || normalized.equals("duelcount") || normalized.equals("count")) comparator = Comparator.comparingInt(DuelLeaderboardEntry::duelCount).reversed();
        else if (normalized.equals("points")) comparator = Comparator.comparingDouble(DuelLeaderboardEntry::totalPoints).reversed();
        else comparator = Comparator.comparingInt(DuelLeaderboardEntry::mmr).reversed();
        comparator = comparator
                .thenComparing((left, right) -> Integer.compare(right.kills(), left.kills()))
                .thenComparing((left, right) -> Integer.compare(right.assists(), left.assists()))
                .thenComparing(entry -> entry.name().toLowerCase(Locale.ROOT));
        entries.sort(comparator);
    }

    private static boolean hasRecordedDuelStats(TameData data) {
        return data != null && data.duelCount > 0;
    }

    private static boolean hasRecordedDuelStats(PlayerDuelStats data) {
        return data != null && data.duelCount > 0;
    }

    private static String resolveDuelPlayerName(MinecraftServer server, UUID playerId, PlayerDuelStats stats) {
        if (server != null) {
            ServerPlayer live = server.getPlayerList().getPlayer(playerId);
            if (live != null) {
                TameRegistry.getOrCreatePlayerDuelStats(playerId, live.getGameProfile().getName());
                return live.getGameProfile().getName();
            }
            if (server.getProfileCache() != null && playerId != null) {
                Optional<GameProfile> profile = server.getProfileCache().get(playerId);
                if (profile.isPresent() && profile.get().getName() != null && !profile.get().getName().isBlank()) {
                    return profile.get().getName();
                }
            }
        }
        if (stats != null && stats.lastKnownName != null && !stats.lastKnownName.isBlank()) {
            return stats.lastKnownName;
        }
        return playerId == null ? "unknown" : playerId.toString();
    }

    private static String formatDuelLeaderboardPoints(double value) {
        double rounded = Math.rint(value);
        if (Math.abs(value - rounded) < 0.0001D) {
            return Integer.toString((int) rounded);
        }
        return String.format(Locale.ROOT, "%.1f", value);
    }

    private static String shortEntityTypeName(String rawType) {
        if (rawType == null || rawType.isBlank()) {
            return "unknown";
        }
        String normalized = rawType.trim().toLowerCase(Locale.ROOT);
        if (normalized.startsWith("entity.")) {
            normalized = normalized.substring("entity.".length());
        }
        int colon = normalized.indexOf(':');
        String path = colon >= 0 ? normalized.substring(colon + 1) : normalized;
        if (path.isBlank()) {
            return normalized;
        }
        int slash = path.lastIndexOf('/');
        if (slash >= 0 && slash < path.length() - 1) {
            path = path.substring(slash + 1);
        }
        return capitalizeWords(path.replace('_', ' '));
    }

    private static int leaderboardInvestedXp(TameData data) {
        return data == null ? 0 : Math.max(0, LevelSystem.estimateInvestedXp(data));
    }

    private static void sendTeleportSummary(ServerPlayer player, String label, int loaded, int unloaded, int deadSkipped, int failed, int xpCost, int crossDimension) {
        if (player == null) {
            return;
        }
        player.sendSystemMessage(buildTeleportSummary(label, loaded, unloaded, deadSkipped, failed, xpCost, crossDimension));
    }

    private static Component buildTeleportSummary(String label, int loaded, int unloaded, int deadSkipped, int failed, int xpCost, int crossDimension) {
        net.minecraft.network.chat.MutableComponent line = Component.literal(label + ": ").withStyle(ChatFormatting.GOLD)
                .append(Component.literal("teleported ").withStyle(ChatFormatting.GRAY))
                .append(Component.literal("(").withStyle(ChatFormatting.DARK_GRAY))
                .append(Component.literal("l:" + loaded).withStyle(ChatFormatting.GREEN))
                .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                .append(Component.literal("u:" + unloaded).withStyle(ChatFormatting.YELLOW))
                .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                .append(Component.literal("d:" + deadSkipped).withStyle(ChatFormatting.DARK_GRAY))
                .append(Component.literal("/").withStyle(ChatFormatting.DARK_GRAY))
                .append(Component.literal("f:" + failed).withStyle(failed > 0 ? ChatFormatting.RED : ChatFormatting.GRAY))
                .append(Component.literal(")").withStyle(ChatFormatting.DARK_GRAY));
        if (xpCost > 0) {
            line = line.append(Component.literal(" xp:" + xpCost).withStyle(ChatFormatting.AQUA));
        }
        if (crossDimension > 0) {
            line = line.append(Component.literal(" xdim:" + crossDimension).withStyle(ChatFormatting.LIGHT_PURPLE));
        }
        return line;
    }

    private static String ownerInitials(MinecraftServer server, UUID ownerUuid) {
        if (ownerUuid == null) {
            return "--";
        }
        String name = null;
        if (server != null) {
            ServerPlayer live = server.getPlayerList().getPlayer(ownerUuid);
            if (live != null) {
                name = live.getGameProfile().getName();
            } else if (server.getProfileCache() != null) {
                java.util.Optional<GameProfile> profile = server.getProfileCache().get(ownerUuid);
                if (profile.isPresent()) {
                    name = profile.get().getName();
                }
            }
        }
        if (name == null || name.isBlank()) {
            return "??";
        }
        String trimmed = name.trim();
        return trimmed.substring(0, Math.min(2, trimmed.length()));
    }

    private static int weightedCombatScore(TameData data) {
        if (data == null) return 0;
        return Math.max(0, data.kills) * 4 + Math.max(0, data.assists);
    }

    static int recentDeaths(CommandSourceStack source, int requestedLimit) {
        ServerPlayer p = source.getPlayer();
        List<DeathHistoryRow> entries = collectDeathHistoryRows(p.getUUID());
        if (entries.isEmpty()) {
            return error(p, "No death history found.");
        }

        int limit = Math.min(Math.max(1, requestedLimit), entries.size());
        p.sendSystemMessage(Component.literal("Last " + limit + " deaths:").withStyle(ChatFormatting.GOLD));
        for (int i = 0; i < limit; i++) {
            DeathHistoryRow r = entries.get(i);
            String when = formatDeathTime(r.unixMillis);
            String where = (r.dimension == null || r.dimension.isBlank())
                    ? "unknown"
                    : (r.dimension + " @ " + r.x + " " + r.y + " " + r.z);
            String how = r.message == null || r.message.isBlank() ? "unknown" : r.message;
            p.sendSystemMessage(Component.literal("[" + r.level + "] ").withStyle(ChatFormatting.YELLOW)
                    .append(Component.literal(r.tameName + " ").withStyle(ChatFormatting.AQUA))
                    .append(Component.literal("\"" + how + "\" ").withStyle(ChatFormatting.GRAY))
                    .append(Component.literal("(" + where + ") ").withStyle(ChatFormatting.DARK_AQUA))
                    .append(Component.literal("{" + when + "}").withStyle(ChatFormatting.DARK_PURPLE)));
        }
        return 1;
    }

    private static List<DeathHistoryRow> collectDeathHistoryRows(UUID ownerUuid) {
        List<DeathHistoryRow> rows = new ArrayList<>();
        for (TameData data : TameRegistry.TAMES.values()) {
            if (data == null || data.ownerUUID == null || !ownerUuid.equals(data.ownerUUID)) continue;
            String tameName = data.name == null ? "unknown" : data.name;
            for (CompoundTag row : data.deathHistory) {
                if (row == null || row.isEmpty()) continue;
                rows.add(new DeathHistoryRow(
                        tameName,
                        row.getInt("level"),
                        row.getString("message"),
                        row.getString("dimension"),
                        row.getInt("x"),
                        row.getInt("y"),
                        row.getInt("z"),
                        row.contains("gameTime", Tag.TAG_LONG) ? row.getLong("gameTime") : 0L,
                        row.contains("unixMillis", Tag.TAG_LONG) ? row.getLong("unixMillis") : 0L
                ));
            }
        }
        // Legacy fallback for worlds that still have old death history records.
        if (rows.isEmpty()) {
            for (TameDeathRecord record : TameRegistry.DEATH_HISTORY) {
                if (record == null || record.ownerUUID == null || !ownerUuid.equals(record.ownerUUID)) continue;
                rows.add(new DeathHistoryRow(
                        record.name,
                        record.level,
                        "",
                        record.deathDimension,
                        record.deathX,
                        record.deathY,
                        record.deathZ,
                        record.deathGameTime,
                        record.deathUnixMillis
                ));
            }
        }
        rows.sort((a, b) -> {
            long ua = a.unixMillis;
            long ub = b.unixMillis;
            if (ua != ub) return Long.compare(ub, ua);
            return Long.compare(b.gameTime, a.gameTime);
        });
        return rows;
    }

    private static String formatDeathTime(long unixMillis) {
        if (unixMillis <= 0L) return "unknown";
        return DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")
                .withZone(ZoneId.systemDefault())
                .format(Instant.ofEpochMilli(unixMillis));
    }

    private static int currentXpPoints(ServerPlayer player) {
        int level = Math.max(0, player.experienceLevel);
        int base = xpPointsAtLevelStart(level);
        int inLevel = (int) Math.floor(player.experienceProgress * player.getXpNeededForNextLevel());
        return Math.max(0, base + Math.max(0, inLevel));
    }

    private static void sendTeleportNames(ServerPlayer player, Collection<? extends LivingEntity> loaded, Collection<TameData> unloaded) {
        if (player == null) return;
        LinkedHashSet<String> names = new LinkedHashSet<>();
        if (loaded != null) {
            for (LivingEntity tame : loaded) {
                if (tame != null) names.add(tame.getName().getString());
            }
        }
        if (unloaded != null) {
            for (TameData data : unloaded) {
                if (data != null) names.add(tameDisplayName(data));
            }
        }
        if (!names.isEmpty()) {
            String teleportMessage = names.size() > 1
                    ? "Teleported " + names.size() + " tames."
                    : "Teleport: " + names.iterator().next() + ".";
            player.sendSystemMessage(Component.literal(teleportMessage).withStyle(ChatFormatting.WHITE));
        }
    }

    private static boolean isAssignedBedTarget(TameData data, SpawnTarget target) {
        if (data == null || target == null || target.level == null || target.pos == null || !data.hasPetBed) return false;
        if (data.petBedDimension == null || !data.petBedDimension.equalsIgnoreCase(target.level.dimension().location().toString())) return false;
        return Math.abs(target.pos.x - (data.petBedX + 0.5D)) < 0.01D
                && Math.abs(target.pos.y - (data.petBedY + 0.8D)) < 0.01D
                && Math.abs(target.pos.z - (data.petBedZ + 0.5D)) < 0.01D;
    }

    private static String compactRecoverNames(Collection<String> rawNames) {
        LinkedHashSet<String> names = new LinkedHashSet<>();
        if (rawNames != null) {
            for (String raw : rawNames) {
                if (raw == null || raw.isBlank()) continue;
                int detail = raw.indexOf(" (");
                String name = stripLevelPrefixes(detail >= 0 ? raw.substring(0, detail) : raw).trim();
                if (!name.isBlank()) names.add(name);
            }
        }
        return String.join(", ", names);
    }

    private static void teleportLivingTameToPlayer(LivingEntity tame, ServerPlayer player) {
        if (tame instanceof TamableAnimal tamable) {
            teleportTameToPlayer(tamable, player);
        } else if (tame != null && player != null) {
            TameData data = TameRegistry.get(tame.getUUID());
            if (data == null) data = TameRegistry.getByTlId(TameData.getTlId(tame));
            clearGuardianAnchor(data);
            LivingEntity moved = TameTransferService.transferInterfaceToLocation(tame, player.serverLevel(),
                    player.getX(), player.getY(), player.getZ(), player.getYRot(), player.getXRot(), data, false);
            if (moved != null && data != null && !data.horseType) applyLivingMovementOverride(moved, data, MovementOrder.FOLLOW);
        }
    }

    private static LiteralArgumentBuilder<CommandSourceStack> debugCommand() {
        return Commands.literal("debug")
                .executes(ctx -> debugStatus(ctx.getSource()))
                .then(Commands.literal("duel")
                        .executes(ctx -> duelToggleStatus(ctx.getSource()))
                        .then(debugDuelBoolean("generall", false, "general"))
                        .then(debugDuelBoolean("general", false, "general"))
                        .then(debugDuelBoolean("duelAssists", false, "assists"))
                        .then(debugDuelBoolean("duelKill", false, "kill"))
                        .then(debugDuelBoolean("duelRanked", true, "general"))
                        .then(debugDuelBoolean("duelSumm", false, "sum"))
                        .then(debugDuelBoolean("kill", false, "kill"))
                        .then(debugDuelBoolean("result", false, "result"))
                        .then(debugDuelBoolean("start", false, "start"))
                        .then(debugDuelBoolean("sum", false, "sum"))
                        .then(debugDuelBoolean("all", false, "all")))
                .then(Commands.literal("ranked")
                        .executes(ctx -> rankedDebugStatus(ctx.getSource()))
                        .then(debugDuelBoolean("general", true, "general"))
                        .then(debugDuelBoolean("kill", true, "kill"))
                        .then(debugDuelBoolean("result", true, "result"))
                        .then(debugDuelBoolean("start", true, "start"))
                        .then(debugDuelBoolean("sum", true, "sum"))
                        .then(debugDuelBoolean("all", true, "all")))
                .then(Commands.literal("inventory")
                        .executes(ctx -> inventoryDebugStatus(ctx.getSource()))
                        .then(Commands.literal("lowOnFood")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setInventoryLowOnFood(ctx.getSource(), BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("noFood")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setInventoryNoFood(ctx.getSource(), BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("sum")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setInventorySummary(ctx.getSource(), BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("sumMin")
                                .then(Commands.argument("minutes", IntegerArgumentType.integer(1))
                                        .executes(ctx -> setInventorySummaryMinutes(ctx.getSource(), IntegerArgumentType.getInteger(ctx, "minutes"))))))
                .then(Commands.literal("combat")
                        .executes(ctx -> combatDebugStatus(ctx.getSource()))
                        .then(Commands.literal("assists")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setCombatDebug(ctx.getSource(), "assists", BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("kills")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setCombatDebug(ctx.getSource(), "kills", BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("death")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setCombatDebug(ctx.getSource(), "death", BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("conflictNoty")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setCombatDebug(ctx.getSource(), "conflictNoty", BoolArgumentType.getBool(ctx, "enabled"))))))
                .then(Commands.literal("other")
                        .executes(ctx -> otherDebugStatus(ctx.getSource()))
                        .then(Commands.literal("NewTame")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setOtherDebug(ctx.getSource(), "newTame", BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("newTame")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setOtherDebug(ctx.getSource(), "newTame", BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("respawnedAutomatically")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setOtherDebug(ctx.getSource(), "autoRespawn", BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("Respawned")
                                .then(Commands.literal("automatically")
                                        .then(Commands.argument("enabled", BoolArgumentType.bool())
                                                .executes(ctx -> setOtherDebug(ctx.getSource(), "autoRespawn", BoolArgumentType.getBool(ctx, "enabled"))))))
                        .then(Commands.literal("generall")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setOtherDebug(ctx.getSource(), "general", BoolArgumentType.getBool(ctx, "enabled")))))
                        .then(Commands.literal("general")
                                .then(Commands.argument("enabled", BoolArgumentType.bool())
                                        .executes(ctx -> setOtherDebug(ctx.getSource(), "general", BoolArgumentType.getBool(ctx, "enabled"))))));
    }

    private static LiteralArgumentBuilder<CommandSourceStack> debugDuelBoolean(String literal, boolean ranked, String category) {
        return Commands.literal(literal)
                .then(Commands.argument("enabled", BoolArgumentType.bool())
                        .executes(ctx -> {
                            boolean enabled = BoolArgumentType.getBool(ctx, "enabled");
                            if ("general".equals(category)) {
                                return ranked ? setRankedDuelGeneral(ctx.getSource(), enabled) : setDuelGeneral(ctx.getSource(), enabled);
                            }
                            if ("assists".equals(category)) {
                                return setDuelAssistMessages(ctx.getSource(), enabled);
                            }
                            return setDuelDebugCategory(ctx.getSource(), ranked, category, enabled);
                        }));
    }

    private static int xpPointsAtLevelStart(int level) {
        if (level <= 16) return level * level + 6 * level;
        if (level <= 31) return (int) (2.5D * level * level - 40.5D * level + 360.0D);
        return (int) (4.5D * level * level - 162.5D * level + 2220.0D);
    }

