    private static int adminResetWolvesBase(CommandSourceStack source) {
        int resetData = 0;
        int resetLoaded = 0;
        for (TameData d : TameRegistry.TAMES.values()) {
            if (!"entity.minecraft.wolf".equalsIgnoreCase(d.type) && !"minecraft:wolf".equalsIgnoreCase(d.type)) continue;
            resetProgressData(d, false);
            resetData++;
        }
        for (var level : source.getServer().getAllLevels()) {
            for (Entity entity : level.getAllEntities()) {
                if (!(entity instanceof Wolf wolf) || !wolf.isTame()) continue;
                setTamableBaseCombatStats(wolf);
                TameData d = TameRegistry.get(wolf.getUUID());
                if (d != null) {
                    LevelSystem.updateTameName(wolf, d);
                }
                wolf.setHealth(wolf.getMaxHealth());
                resetLoaded++;
            }
        }
        TameRegistry.markDirty();
        final int loadedCount = resetLoaded;
        final int dataCount = resetData;
        source.sendSuccess(() -> Component.literal("Reset wolf base stats for " + loadedCount + " loaded wolves; reset progress data for " + dataCount + " wolf entries."), true);
        return 1;
    }

    private static int adminListSummonTypes(CommandSourceStack source) {
        List<String> types = new ArrayList<>(TameRegistry.getSummonTypes());
        types.sort(String::compareToIgnoreCase);
        source.sendSuccess(() -> Component.literal("Summon entity types: "
                + (types.isEmpty() ? "none" : String.join(", ", types))).withStyle(ChatFormatting.YELLOW), false);
        return 1;
    }

    private static int adminAddSummonType(CommandSourceStack source, String typeId) {
        ResourceLocation id = ResourceLocation.tryParse(typeId == null ? "" : typeId.trim().toLowerCase(Locale.ROOT));
        if (id == null || !ForgeRegistries.ENTITY_TYPES.containsKey(id)) return adminError(source, "Unknown entity type: " + typeId + ".");
        if (!TameRegistry.addSummonType(id.toString())) return adminError(source, "Entity type is already marked as a summon: " + id + ".");

        int loadedDetached = 0;
        for (ServerLevel level : source.getServer().getAllLevels()) {
            for (Entity entity : level.getAllEntities()) {
                ResourceLocation entityId = ForgeRegistries.ENTITY_TYPES.getKey(entity.getType());
                if (!id.equals(entityId) || !(entity instanceof LivingEntity living)) continue;
                TameData data = TameRegistry.get(living.getUUID());
                if (data == null) {
                    UUID tlId = TameData.getTlId(living);
                    data = tlId == null ? null : TameRegistry.getByTlId(tlId);
                }
                if (data != null) {
                    if (data.name != null && !data.name.isBlank()) living.setCustomName(Component.literal(data.name));
                    TameRegistry.removeDeathsForIdentity(data.uuid, data.tlId);
                    TameRegistry.remove(data.uuid);
                    loadedDetached++;
                }
                living.getPersistentData().remove(TameData.TL_ID_TAG);
            }
        }

        List<TameData> registered = new ArrayList<>(TameRegistry.TAMES.values());
        int registryRemoved = 0;
        for (TameData data : registered) {
            if (data == null || data.uuid == null || !id.toString().equals(normalizedStoredType(data.type))) continue;
            TameRegistry.removeDeathsForIdentity(data.uuid, data.tlId);
            TameRegistry.remove(data.uuid);
            registryRemoved++;
        }
        int finalLoadedDetached = loadedDetached;
        int finalRegistryRemoved = registryRemoved;
        source.sendSuccess(() -> Component.literal("Marked " + id + " as a summon type. Detached "
                + finalLoadedDetached + " loaded entities and removed " + finalRegistryRemoved + " unloaded registry entries. No entities were terminated.")
                .withStyle(ChatFormatting.GREEN), true);
        return 1;
    }

    private static int adminRemoveSummonType(CommandSourceStack source, String typeId) {
        if (!TameRegistry.removeSummonType(typeId)) return adminError(source, "Entity type is not marked as a summon: " + typeId + ".");
        source.sendSuccess(() -> Component.literal("Removed summon classification from " + typeId + ".")
                .withStyle(ChatFormatting.GREEN), true);
        return 1;
    }

    private static String normalizedStoredType(String typeId) {
        if (typeId == null) return "";
        String normalized = typeId.trim().toLowerCase(Locale.ROOT);
        return normalized.startsWith("entity.") ? normalized.substring("entity.".length()) : normalized;
    }

    private static int adminRebuildEnderDragonArena(CommandSourceStack source) {
        ServerLevel end = source.getServer().getLevel(Level.END);
        if (end == null) {
            return error(source.getPlayer(), "The End dimension is unavailable.");
        }

        List<SpikeFeature.EndSpike> spikes = SpikeFeature.getSpikesForLevel(end);
        int removedCrystals = 0;
        for (SpikeFeature.EndSpike spike : spikes) {
            List<EndCrystal> existing = end.getEntitiesOfClass(EndCrystal.class, spike.getTopBoundingBox());
            removedCrystals += existing.size();
            existing.forEach(Entity::discard);

            BlockPos origin = new BlockPos(spike.getCenterX(), 64, spike.getCenterZ());
            end.getChunkAt(origin);
            Feature.END_SPIKE.place(
                    new SpikeConfiguration(false, List.of(spike), null),
                    end,
                    end.getChunkSource().getGenerator(),
                    end.random,
                    origin
            );
        }

        boolean activePortal = end.getDragons().isEmpty();
        BlockPos podium = new BlockPos(0, 64, 0);
        end.getChunkAt(podium);
        new EndPodiumFeature(activePortal).place(
                FeatureConfiguration.NONE,
                end,
                end.getChunkSource().getGenerator(),
                end.random,
                podium
        );
        if (end.getDragonFight() != null) {
            end.getDragonFight().resetSpikeCrystals();
        }

        int finalRemovedCrystals = removedCrystals;
        source.sendSuccess(() -> Component.literal("Rebuilt the Ender Dragon arena: 10 spikes, crystals, cages, and central podium. Replaced "
                + finalRemovedCrystals + " existing spike crystal" + (finalRemovedCrystals == 1 ? "." : "s.")
                + (activePortal ? " Exit portal is active." : " Exit portal remains inactive while the dragon is alive."))
                .withStyle(ChatFormatting.GREEN), true);
        return 1;
    }

    private static int warnDeleteEnderDragonChunks(CommandSourceStack source) {
        source.sendFailure(Component.literal("This permanently resets the 25x25 End chunks centered on chunk 0,0 while the server stays online. "
                + "Everyone must leave the End first. Run /tames admin deleteEnderDragonChunks confirm."));
        return 0;
    }

    private static int adminDeleteEnderDragonChunks(CommandSourceStack source) {
        if (pendingLiveEndArenaReset) return adminError(source, "An End arena reset is already in progress.");
        ServerLevel end = source.getServer().getLevel(Level.END);
        if (end == null) return adminError(source, "The End dimension is unavailable.");
        if (!end.players().isEmpty()) return adminError(source, "Everyone must leave the End before its arena chunks can be reset.");
        for (long forced : end.getForcedChunks()) {
            int x = ChunkPos.getX(forced);
            int z = ChunkPos.getZ(forced);
            if (isEndArenaResetChunk(x, z)) {
                return adminError(source, "Chunk " + x + ", " + z + " is force-loaded. Unforce it before resetting the arena.");
            }
        }

        List<Entity> entities = new ArrayList<>();
        end.getAllEntities().forEach(entity -> {
            ChunkPos pos = entity.chunkPosition();
            if (isEndArenaResetChunk(pos.x, pos.z)) entities.add(entity);
        });
        entities.forEach(Entity::discard);
        pendingLiveEndArenaReset = true;
        pendingLiveEndArenaResetStarted = source.getServer().getTickCount();
        pendingLiveEndArenaResetRequester = source.getEntity() instanceof ServerPlayer player ? player.getUUID() : null;
        source.sendSuccess(() -> Component.literal("Live End arena reset started. The server is unloading and deleting chunks -12..12; keep everyone out of the End until completion.")
                .withStyle(ChatFormatting.YELLOW), true);
        return 1;
    }

    private static boolean isEndArenaResetChunk(int x, int z) {
        return Math.abs(x) <= END_ARENA_RESET_CHUNK_RADIUS && Math.abs(z) <= END_ARENA_RESET_CHUNK_RADIUS;
    }

    private static void processPendingLiveEndArenaReset(MinecraftServer server) {
        if (!pendingLiveEndArenaReset) return;
        ServerLevel end = server.getLevel(Level.END);
        if (end == null) {
            finishLiveEndArenaReset(server, false, "The End dimension became unavailable; reset cancelled.");
            return;
        }
        if (!end.players().isEmpty()) {
            finishLiveEndArenaReset(server, false, "A player entered the End; reset cancelled before deletion.");
            return;
        }
        for (int x = -END_ARENA_RESET_CHUNK_RADIUS; x <= END_ARENA_RESET_CHUNK_RADIUS; x++) {
            for (int z = -END_ARENA_RESET_CHUNK_RADIUS; z <= END_ARENA_RESET_CHUNK_RADIUS; z++) {
                if (end.getChunkSource().getChunkNow(x, z) != null) {
                    if (server.getTickCount() - pendingLiveEndArenaResetStarted > 20L * 30L) {
                        finishLiveEndArenaReset(server, false, "The arena chunks did not unload within 30 seconds. Check for chunk loaders and try again.");
                    }
                    return;
                }
            }
        }

        for (int x = -END_ARENA_RESET_CHUNK_RADIUS; x <= END_ARENA_RESET_CHUNK_RADIUS; x++) {
            for (int z = -END_ARENA_RESET_CHUNK_RADIUS; z <= END_ARENA_RESET_CHUNK_RADIUS; z++) {
                end.getChunkSource().chunkMap.write(new ChunkPos(x, z), null);
            }
        }
        end.getChunkSource().chunkMap.flushWorker();
        finishLiveEndArenaReset(server, true, "Deleted the 25x25 End arena chunks while the server remained online. They will regenerate when a player returns.");
    }

    private static void finishLiveEndArenaReset(MinecraftServer server, boolean success, String message) {
        UUID requester = pendingLiveEndArenaResetRequester;
        pendingLiveEndArenaReset = false;
        pendingLiveEndArenaResetRequester = null;
        ServerPlayer player = requester == null ? null : server.getPlayerList().getPlayer(requester);
        Component component = Component.literal(message).withStyle(success ? ChatFormatting.GREEN : ChatFormatting.RED);
        if (player != null) player.sendSystemMessage(component);
        DomesticationMod.LOGGER.info("[END-ARENA-RESET] {}", message);
    }

    private static int adminResetServerProgress(CommandSourceStack source) {
        int resetData = TameRegistry.TAMES.size();
        int resetDeaths = TameRegistry.DEATH_HISTORY.size();
        int resetLoaded = 0;
        int clearedRespawnRequests = 0;
        // Normalize loaded tame entities first so stale attribute bonuses are removed immediately.
        TameRegistry.LAST_DEATHS.clear();
        for (var level : source.getServer().getAllLevels()) {
            for (Entity entity : level.getAllEntities()) {
                if (!(entity instanceof TamableAnimal tame) || !tame.isTame()) continue;
                setTamableBaseCombatStats(tame);
                tame.setHealth(tame.getMaxHealth());
                resetLoaded++;
            }
        }
        // Wipe all persisted progression/history as if the mod was freshly installed.
        TameRegistry.TAMES.clear();
        TameRegistry.LAST_DEATHS.clear();
        TameRegistry.DEATH_HISTORY.clear();
        DIWorldData worldData = DIWorldData.get(source.getLevel());
        if (worldData != null) {
            clearedRespawnRequests = worldData.clearAllRespawnRequests();
        }
        TameRegistry.markDirty();
        final int loadedCount = resetLoaded;
        final int dataCount = resetData;
        final int deathCount = resetDeaths;
        final int clearedRequests = clearedRespawnRequests;
        source.sendSuccess(() -> Component.literal("Server progress fully wiped: " + dataCount + " tame entries, " + deathCount + " death-history entries, " + clearedRequests + " queued bed respawns, and " + loadedCount + " loaded tames normalized to base stats."), true);
        return 1;
    }

    private static int adminResetDuelLeaderboards(CommandSourceStack source) {
        int tameEntries = 0;
        for (TameData data : TameRegistry.TAMES.values()) {
            if (data != null && data.duelCount > 0) {
                tameEntries++;
            }
        }
        int playerEntries = TameRegistry.getPlayerDuelStats().size();
        TameRegistry.resetAllDuelStats();
        final int finalTameEntries = tameEntries;
        final int finalPlayerEntries = playerEntries;
        source.sendSuccess(() -> Component.literal("Reset duel leaderboard data for " + finalTameEntries + " tames and " + finalPlayerEntries + " players.").withStyle(ChatFormatting.YELLOW), true);
        return 1;
    }

    private static int adminRemoveDuelLeaderboardEntry(CommandSourceStack source, String rawEntry) {
        String entry = normalizeDuelLeaderboardLookup(rawEntry);
        if (entry.isBlank()) {
            return error(source.getPlayer(), "Use a tame/player name or UUID.");
        }
        String lookup = extractDuelLeaderboardLookup(entry);
        UUID uuid = extractUuidFromDuelLeaderboardLookup(entry);
        List<TameData> tameMatches = new ArrayList<>();
        for (TameData data : TameRegistry.TAMES.values()) {
            if (data == null || !hasRecordedDuelStats(data)) {
                continue;
            }
            if ((uuid != null && (uuid.equals(data.uuid) || uuid.equals(data.tlId)))
                    || duelLeaderboardNameMatches(data.name, lookup)
                    || duelLeaderboardNameMatches(tameDisplayName(data), lookup)) {
                tameMatches.add(data);
            }
        }
        List<Map.Entry<UUID, PlayerDuelStats>> playerMatches = new ArrayList<>();
        for (Map.Entry<UUID, PlayerDuelStats> playerEntry : TameRegistry.getPlayerDuelStats().entrySet()) {
            UUID playerId = playerEntry.getKey();
            PlayerDuelStats stats = playerEntry.getValue();
            if (playerId == null || stats == null || !hasRecordedDuelStats(stats)) {
                continue;
            }
            String playerName = resolveDuelPlayerName(source.getServer(), playerId, stats);
            if ((uuid != null && uuid.equals(playerId)) || duelLeaderboardNameMatches(playerName, lookup)) {
                playerMatches.add(playerEntry);
            }
        }
        int totalMatches = tameMatches.size() + playerMatches.size();
        if (totalMatches <= 0) {
            return error(source.getPlayer(), "No duel leaderboard entry matched '" + entry + "'.");
        }
        if (totalMatches > 1 && uuid == null) {
            return error(source.getPlayer(), "Ambiguous duel leaderboard entry (" + totalMatches + " matches). Use the UUID from autocomplete.");
        }
        if (!tameMatches.isEmpty()) {
            TameData data = tameMatches.get(0);
            resetDuelStats(data);
            TameRegistry.markDirty();
            source.sendSuccess(() -> Component.literal("Removed duel leaderboard entry for tame " + tameDisplayName(data) + ".").withStyle(ChatFormatting.YELLOW), true);
            return 1;
        }
        UUID playerId = playerMatches.get(0).getKey();
        String playerName = resolveDuelPlayerName(source.getServer(), playerId, playerMatches.get(0).getValue());
        TameRegistry.removePlayerDuelStats(playerId);
        source.sendSuccess(() -> Component.literal("Removed duel leaderboard entry for player " + playerName + ".").withStyle(ChatFormatting.YELLOW), true);
        return 1;
    }

    private static void resetDuelStats(TameData data) {
        if (data == null) {
            return;
        }
        data.duelMmr = PlayerDuelStats.DEFAULT_MMR;
        data.duelKills = 0;
        data.duelAssists = 0;
        data.duelDeaths = 0;
        data.duelWins = 0;
        data.duelLosses = 0;
        data.duelCount = 0;
        data.duelPoints = 0.0D;
    }

    private static String extractDuelLeaderboardLookup(String rawEntry) {
        String entry = normalizeDuelLeaderboardLookup(rawEntry);
        int slash = entry.lastIndexOf('/');
        if (slash >= 0 && slash + 1 < entry.length()) {
            String tail = entry.substring(slash + 1).trim();
            if (parseUuidOrNull(tail) != null) {
                String head = entry.substring(0, slash).trim();
                return head.isBlank() ? tail : head;
            }
        }
        return entry;
    }

    private static String normalizeDuelLeaderboardLookup(String raw) {
        String value = raw == null ? "" : raw.trim();
        if (value.length() >= 2 && ((value.startsWith("\"") && value.endsWith("\"")) || (value.startsWith("'") && value.endsWith("'")))) {
            value = value.substring(1, value.length() - 1).trim();
        }
        return value;
    }

    private static UUID extractUuidFromDuelLeaderboardLookup(String rawEntry) {
        String entry = normalizeDuelLeaderboardLookup(rawEntry);
        UUID direct = parseUuidOrNull(entry);
        if (direct != null) {
            return direct;
        }
        int slash = entry.lastIndexOf('/');
        if (slash >= 0 && slash + 1 < entry.length()) {
            UUID tail = parseUuidOrNull(entry.substring(slash + 1).trim());
            if (tail != null) {
                return tail;
            }
        }
        for (String token : entry.split("\\s+")) {
            UUID tokenUuid = parseUuidOrNull(token);
            if (tokenUuid != null) {
                return tokenUuid;
            }
        }
        return null;
    }

    private static boolean duelLeaderboardNameMatches(String candidate, String lookup) {
        String left = normalizeDuelLeaderboardName(candidate);
        String right = normalizeDuelLeaderboardName(lookup);
        return !left.isBlank() && left.equalsIgnoreCase(right);
    }

    private static String normalizeDuelLeaderboardName(String name) {
        String cleaned = stripLevelPrefixes(normalizeDuelLeaderboardLookup(name));
        return cleaned.replaceAll("\\s+", " ").trim();
    }

    private static UUID parseUuidOrNull(String raw) {
        try {
            return raw == null || raw.isBlank() ? null : UUID.fromString(raw.trim());
        } catch (IllegalArgumentException ex) {
            return null;
        }
    }

    private static int adminSetClass(CommandSourceStack source, String petName, String className) {
        TameClass tameClass = TameClass.parse(className);
        if (tameClass == null) {
            return error(source.getPlayer(), "Unknown class. Use one of: " + String.join(", ", classNames()));
        }

        List<TameData> matches = findAliveTamesByName(petName);
        if (matches.isEmpty()) {
            return error(source.getPlayer(), "No alive tame found with that name.");
        }
        if (matches.size() > 1) {
            return error(source.getPlayer(), "Ambiguous tame name (" + matches.size() + " matches). Rename duplicates first.");
        }

        TameData data = matches.get(0);
        data.tameClass = tameClass;
        TameRegistry.markDirty();

        TamableAnimal tame = findLoadedTameByUuid(source, data.uuid);
        if (tame != null) {
            LevelSystem.updateTameName(tame, data);
        }

        source.sendSuccess(() -> Component.literal("Set class of " + data.name + " to " + tameClass.id() + "."), true);
        return 1;
    }

    private static int adminRebuildPet(CommandSourceStack source, String petName, String className) {
        ServerPlayer player = source.getPlayer();
        TameClass tameClass = TameClass.parse(className);
        if (tameClass == null) {
            return error(player, "Unknown class. Use one of: " + String.join(", ", classNames()));
        }

        TameData data = resolveAdminAliveTame(player, petName);
        if (data == null) {
            return 0;
        }
        Entity entity = findLoadedTameByUuid(source, data.uuid);
        if (!(entity instanceof TamableAnimal tame) || !tame.isTame() || !tame.isAlive()) {
            return error(player, "Pet is not loaded.");
        }

        int previousLevel = Math.max(1, data.level);
        int previousKills = data.kills;
        int previousAssists = data.assists;
        int targetXp = totalXpToReachLevel(previousLevel);

        LevelSystem.resetProgress(tame, data);
        clearSavedProgress(data);
        data.levelRewardHistory.clear();
        data.tameClass = tameClass;
        data.kills = previousKills;
        data.assists = previousAssists;
        data.xp = 0;
        data.xpToNext = LevelSystem.xpRequiredForLevel(1);
        data.cooldowns.clear();
        TameRegistry.markDirty();

        if (targetXp > 0) {
            LevelSystem.grantXP(tame, data, targetXp);
        } else {
            LevelSystem.updateTameName(tame, data);
            tame.setHealth(tame.getMaxHealth());
            TameRegistry.markDirty();
        }

        int rebuiltLevel = data.level;
        source.sendSuccess(() -> Component.literal(
                "Rebuilt " + data.name + " as " + tameClass.id() + " and rerolled progression back to level " + rebuiltLevel + "."
        ), true);
        return 1;
    }

    private static int totalXpToReachLevel(int targetLevel) {
        int total = 0;
        for (int level = 1; level < Math.max(1, targetLevel); level++) {
            total += LevelSystem.xpRequiredForLevel(level);
        }
        return total;
    }

    private static void clearSavedProgress(TameData data) {
        if (data == null) {
            return;
        }
        data.hasSavedProgress = false;
        data.savedProgressCost = 0;
        data.savedLevel = 1;
        data.savedXp = 0;
        data.savedXpToNext = LevelSystem.xpRequiredForLevel(1);
        data.savedKills = 0;
        data.savedAssists = 0;
        data.savedBonusHealth = 0.0D;
        data.savedBonusDamage = 0.0D;
        data.savedBonusSpeed = 0.0D;
        data.savedBonusArmor = 0.0D;
        data.savedBonusArmorToughness = 0.0D;
        data.savedBonusKnockback = 0.0D;
        data.savedBonusKnockbackResist = 0.0D;
        data.savedAbilities.clear();
        data.savedAbilityLevels.clear();
        data.savedAttributeLevels.clear();
    }

    private static int adminMigrateProtectorToSupporter(CommandSourceStack source) {
        int affected = 0;
        for (TameData data : TameRegistry.TAMES.values()) {
            if (data == null || data.tameClass != TameClass.SUPPORTER) {
                continue;
            }
            data.tameClass = TameClass.SUPPORTER;
            affected++;
        }
        if (affected > 0) {
            TameRegistry.markDirty();
        }
        final int migrated = affected;
        source.sendSuccess(() -> Component.literal("Protector -> supporter migration applied to " + migrated + " tame entries."), true);
        return 1;
    }

